const PHOTO_IMPORT_SOURCE_OPTIONS: Array<{ kind: PhotoImportSourceKind; label: string }> = [
  { kind: "folder", label: "Files/folders" },
  { kind: "camera", label: "Camera/device" },
  { kind: "library", label: "Photo library" },
  { kind: "mail", label: "Mail" },
  { kind: "safari", label: "Safari" },
  { kind: "messages", label: "Messages" },
  { kind: "airdrop", label: "AirDrop" },
  { kind: "downloads", label: "Downloads" },
  { kind: "app", label: "Other app" },
];

function photoImportSourceLabel(kind: PhotoImportSourceKind, fallback: string, preserveFallback = false): string {
  const cleanFallback = String(fallback || "").trim();
  if (preserveFallback && cleanFallback) return cleanFallback;
  if (kind === "folder") return cleanFallback;
  return PHOTO_IMPORT_SOURCE_OPTIONS.find((option) => option.kind === kind)?.label || cleanFallback;
}

function photoImportReviewSourceLabel(kind: PhotoImportSourceKind, fallback: string, preserveFallback = false): string {
  const label = photoImportSourceLabel(kind, fallback, preserveFallback);
  if (!preserveFallback || kind === "folder") return label;
  const kindLabel = PHOTO_IMPORT_SOURCE_OPTIONS.find((option) => option.kind === kind)?.label || "";
  if (!label || !kindLabel || label.toLowerCase() === kindLabel.toLowerCase()) return label || kindLabel;
  return `${label} · ${kindLabel}`;
}

function photoImportSourceKindFromInference(kind: PhotoImportInferredSourceKind): PhotoImportSourceKind {
  return PHOTO_IMPORT_SOURCE_OPTIONS.some((option) => option.kind === kind) ? kind : "folder";
}

function normalizeExternalPhotoImportSourceKind(kind?: PhotoImportSourceKind | string): PhotoImportSourceKind {
  return PHOTO_IMPORT_SOURCE_OPTIONS.some((option) => option.kind === kind) ? kind as PhotoImportSourceKind : "folder";
}

const emptyRules: PhotoAlbumRules = {};

function normalizePhotoBurstStackItem(value: unknown): PhotoBurstStackItem | null {
  if (!value || typeof value !== "object") return null;
  const item = value as Record<string, unknown>;
  const sourcePath = String(item.sourcePath || "").trim();
  if (!sourcePath) return null;
  const sequence = Number(item.sequence || 0);
  return {
    assetId: String(item.assetId || ""),
    sourcePath,
    mediaKind: String(item.mediaKind || ""),
    title: String(item.title || ""),
    captureDate: String(item.captureDate || ""),
    sequence: Number.isFinite(sequence) && sequence > 0 ? sequence : 0,
    keeper: Boolean(item.keeper),
    selectionRole: String(item.selectionRole || ""),
    selectedAt: String(item.selectedAt || ""),
    coverHint: Boolean(item.coverHint),
  };
}

function normalizePhotoBurstStack(value: unknown): PhotoBurstStack | null {
  if (!value || typeof value !== "object") return null;
  const stack = value as Record<string, unknown>;
  const stackId = String(stack.stackId || "").trim();
  const sourcePaths = Array.isArray(stack.sourcePaths)
    ? stack.sourcePaths.map((sourcePath) => String(sourcePath || "").trim()).filter(Boolean)
    : [];
  const items = Array.isArray(stack.items)
    ? stack.items.map(normalizePhotoBurstStackItem).filter(Boolean) as PhotoBurstStackItem[]
    : sourcePaths.map((sourcePath, index) => ({
      assetId: "",
      sourcePath,
      mediaKind: "burst",
      title: "",
      captureDate: "",
      sequence: index + 1,
      keeper: false,
      selectionRole: "",
      selectedAt: "",
      coverHint: sourcePath === String(stack.coverSourcePath || ""),
    }));
  if (!stackId || (!sourcePaths.length && !items.length)) return null;
  const count = Number(stack.count || items.length || sourcePaths.length);
  const keeperCount = Number(stack.keeperCount || items.filter((item) => item.keeper).length);
  return {
    stackId,
    name: String(stack.name || "Burst"),
    count: Number.isFinite(count) && count > 0 ? count : items.length || sourcePaths.length,
    keeperCount: Number.isFinite(keeperCount) && keeperCount > 0 ? keeperCount : 0,
    coverSourcePath: String(stack.coverSourcePath || ""),
    sourcePaths: sourcePaths.length ? sourcePaths : items.map((item) => item.sourcePath),
    items,
  };
}

function normalizePhotoBurstStackList(value: unknown): PhotoBurstStack[] {
  if (!value || typeof value !== "object") return [];
  const rawStacks = (value as { stacks?: unknown }).stacks;
  if (!Array.isArray(rawStacks)) return [];
  return rawStacks.map(normalizePhotoBurstStack).filter(Boolean) as PhotoBurstStack[];
}

function albumTreeItemId(folder: PhotoFolder): string {
  if (folder.kind === "album") return folder.albumId || folder.id.replace(/^album:/, "");
  if (folder.kind === "albumFolder") return folder.folderId || folder.id.replace(/^albumFolder:/, "");
  return "";
}

function albumTreeParentId(folder: PhotoFolder): string {
  if (folder.kind === "album") return folder.folderId || "";
  if (folder.kind === "albumFolder") return folder.parentFolderId || "";
  return "";
}

function albumTreePosition(folder: PhotoFolder): number {
  const value = folder.kind === "album" ? folder.folderPosition : folder.position;
  return typeof value === "number" && Number.isFinite(value) ? value : 2_147_483_647;
}

function albumTreeSiblings(folder: PhotoFolder | null, folders: PhotoFolder[]): PhotoFolder[] {
  if (!folder || (folder.kind !== "album" && folder.kind !== "albumFolder")) return [];
  const parentId = albumTreeParentId(folder);
  return folders
    .filter((item) => {
      if (item.kind !== "album" && item.kind !== "albumFolder") return false;
      return albumTreeParentId(item) === parentId && Boolean(albumTreeItemId(item));
    })
    .sort((a, b) => {
      const position = albumTreePosition(a) - albumTreePosition(b);
      if (position) return position;
      const name = String(a.name || "").localeCompare(String(b.name || ""));
      if (name) return name;
      return albumTreeItemId(a).localeCompare(albumTreeItemId(b));
    });
}

function albumTreeAncestorIds(folder: PhotoFolder | undefined, folders: PhotoFolder[]): string[] {
  if (!folder || (folder.kind !== "album" && folder.kind !== "albumFolder")) return [];
  const byFolderId = new Map(
    folders
      .filter((item) => item.kind === "albumFolder")
      .map((item) => [albumTreeItemId(item), item])
  );
  const ancestors: string[] = [];
  const seen = new Set<string>();
  let parentId = albumTreeParentId(folder);
  while (parentId && byFolderId.has(parentId) && !seen.has(parentId)) {
    seen.add(parentId);
    ancestors.push(parentId);
    parentId = albumTreeParentId(byFolderId.get(parentId) as PhotoFolder);
  }
  return ancestors;
}

function photoStatusFilterLabel(status: CandidateStatus): string {
  if (status === "pending") return "Needs review";
  if (status === "accepted") return "Accepted";
  if (status === "uncertain") return "Not sure";
  return "Rejected";
}

function parsePhotoPeopleDraft(value: string): string[] {
  const people: string[] = [];
  const seen = new Set<string>();
  for (const raw of value.split(/[,;\n]/)) {
    const person = raw.trim().replace(/\s+/g, " ");
    const key = person.toLowerCase();
    if (!person || seen.has(key)) continue;
    seen.add(key);
    people.push(person);
  }
  return people;
}

function photoPeopleDraftValue(values?: string[]): string {
  return (values || []).filter(Boolean).join(", ");
}

function savedPeopleGroupId(folder: PhotoFolder): string {
  if (folder.kind !== "group") return "";
  return folder.groupId || (folder.id.startsWith("group:saved:") ? folder.id.slice("group:saved:".length) : "");
}

function photoDuplicateGroupLabel(group: PhotoDuplicateGroup | null | undefined, uiText: (source: string) => string): string {
  if (!group) return uiText("None");
  if (group.algorithm === "exact_hash") return uiText("Exact duplicate");
  if (group.algorithm === "perceptual_dhash") return uiText("Near duplicate");
  return uiText("Duplicate group");
}

function photoDuplicateRecommendationText(
  group: PhotoDuplicateGroup | null | undefined,
  currentAssetId: string,
  fileName: (sourcePath: string) => string,
  uiText: (source: string) => string
): string {
  if (!group?.recommendedAssetId) return uiText("None");
  const target = group.recommendedAssetId === currentAssetId
    ? uiText("This photo")
    : fileName(group.recommendedSourcePath || group.recommendedAssetId);
  const reasons = (group.recommendationReasons || []).map((reason) => uiText(reason)).filter(Boolean).slice(0, 3);
  return reasons.length ? `${target} · ${reasons.join(", ")}` : target;
}

function placeMapClusterRadius(zoomLevel: number): number {
  const index = Math.max(0, Math.min(PHOTO_PLACE_MAP_CLUSTER_RADII.length - 1, Math.round(zoomLevel) - 1));
  return PHOTO_PLACE_MAP_CLUSTER_RADII[index];
}

function isUtilityCoverAllowed(folder: PhotoFolder | null | undefined): folder is PhotoFolder {
  if (!folder || folder.kind !== "utility") return false;
  if (folder.id.startsWith("media:") || folder.id.startsWith("utility:")) return true;
  return [
    "favorites",
    "recentlyAdded",
    "recentlySaved",
    "recentlyEdited",
    "recentlyViewed",
    "recentlyShared",
    "duplicates",
    "places",
    "trips",
    "memories",
    "pets",
    "petReview",
  ].includes(folder.id);
}

