  const photoRepairScopeFallbackName = photoRepairScopePath.split(/[\\/]/).filter(Boolean).pop() || photoRepairScopePath;
  const photoRepairScopeName = photoRepairScopePath
    ? String(photoBackupCheck?.scope?.label || "").trim() || photoRepairScopeFallbackName
    : uiText("All libraries");
  const photoRepairScopeLabel = photoRepairScopePath
