    setGroupNameDraft(activeGroup.name || "");
    setGroupPeopleDraft(photoPeopleDraftValue(activeGroupPeople));
    setGroupExcludePeopleDraft(photoPeopleDraftValue(activeGroupExcludedPeople));
    setGroupPetsDraft(photoPeopleDraftValue(activeGroupPets));
    setGroupExcludePetsDraft(photoPeopleDraftValue(activeGroupExcludedPets));
