    const resultCount = librarySearchKeyboardItems.length;
    const panelOpen = !sensitiveCollectionLocked && searchQuery.trim().length >= 2 && librarySearchHasResults && resultCount > 0;
    if (event.key === "Escape") {
      if (librarySearchActiveIndex >= 0) {
        event.preventDefault();
        setLibrarySearchActiveIndex(-1);
        return;
      }
      if (searchQuery) {
        event.preventDefault();
        updatePhotoSearchQuery("");
      }
      return;
    }
    if (!panelOpen) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      setLibrarySearchActiveIndex((current) => {
        const base = current >= 0 ? current : event.key === "ArrowDown" ? -1 : 0;
        return event.key === "ArrowDown"
          ? (base + 1) % resultCount
          : (base - 1 + resultCount) % resultCount;
      });
      return;
    }
    if (event.key === "Enter" && librarySearchActiveItem) {
      event.preventDefault();
      openLibrarySearchItem(librarySearchActiveItem);
    }
