  async function reviewInlineCandidate(candidate: ReviewCandidate, status: CandidateStatus) {
    if (!candidate.candidateId) return;
    const previousStatus = candidate.status;
    setInlineReviewSavingId(candidate.candidateId);
    try {
      await reviewCandidate(status, candidate);
      setInlineReviewDecisions((current) => {
        const next = normalizePhotoInlineReviewDecisions([
          {
            id: `${candidate.candidateId}:${Date.now()}`,
            candidateId: candidate.candidateId,
            personName: candidate.personName,
            sourcePath: candidate.sourcePath,
            previousStatus,
            status,
            score: candidate.score,
            decidedAt: new Date().toISOString(),
          },
          ...current.filter((item) => item.candidateId !== candidate.candidateId),
        ]);
        storePhotoInlineReviewDecisions(PHOTO_INLINE_REVIEW_DECISIONS_KEY, next);
        return next;
      });
      await loadPhotoOperations();
    } finally {
      setInlineReviewSavingId((current) => current === candidate.candidateId ? "" : current);
    }
  }

  function clearInlineReviewDecisionHistory() {
    setInlineReviewDecisions([]);
    storePhotoInlineReviewDecisions(PHOTO_INLINE_REVIEW_DECISIONS_KEY, []);
  }

  function renderReviewDecisionOperation(operation: PhotoOperation) {
    const payload = operation.payload && typeof operation.payload === "object" ? operation.payload : {};
    const sourcePath = String(payload.sourcePath || "");
    const sourceName = String(payload.sourceFilename || "") || fileName(sourcePath);
    const personName = String(payload.personName || uiText("Unknown person"));
    const statusBeforeValue = photoStatusFilterValue(String(payload.statusBefore || ""));
    const statusAfterValue = photoStatusFilterValue(String(payload.statusAfter || ""));
    const statusBefore = statusBeforeValue ? photoStatusFilterLabel(statusBeforeValue) : "";
    const statusAfter = statusAfterValue ? photoStatusFilterLabel(statusAfterValue) : "";
    const score = Number(payload.scoreAfter ?? payload.scoreBefore);
    const quality = Number(payload.qualityAfter ?? payload.qualityBefore);
    const details = [
      sourceName,
      statusBefore || statusAfter ? `${statusBefore || uiText("unknown")} -> ${statusAfter || uiText("unknown")}` : "",
      Number.isFinite(score) && score > 0 ? `${uiText("score")} ${Math.round(score * 100)}%` : "",
      Number.isFinite(quality) && quality > 0 ? `${uiText("quality")} ${Math.round(quality * 100)}%` : "",
      operation.canUndo ? uiText("Undoable") : uiText("Undone"),
    ].filter(Boolean).join(" · ");
    return (
      <article key={operation.operationId}>
        <Clock size={13} />
        <span>{personName}</span>
        <small>{details}</small>
        <time dateTime={operation.createdAt}>{formatDateText(operation.createdAt) || uiText("Just now")}</time>
      </article>
    );
  }

  function reviewMoreForManagedPerson(folder: PhotoFolder) {
    const personName = folder.name.trim().toLowerCase();
    if (!personName) return;
    const candidateIds = reviewCandidates
      .filter((candidate) => candidate.personName.trim().toLowerCase() === personName)
      .filter((candidate) => candidate.status === "pending" || candidate.status === "uncertain")
      .sort((a, b) => b.score - a.score || b.quality - a.quality || a.candidateId.localeCompare(b.candidateId))
      .map((candidate) => candidate.candidateId);
    if (!candidateIds.length) return;
    openReviewForCandidates(candidateIds, { label: `${folder.name} ${uiText("Review More")}` });
  }

  function reviewCandidatesForManagedGroup(folder: PhotoFolder): ReviewCandidate[] {
    const memberPeople = folder.groupProfile?.memberPeople || folder.groupPeople || [];
    const excludePeople = folder.groupProfile?.excludePeople || folder.excludePeople || [];
    return buildPhotoGroupReviewCandidates({
      candidates: reviewCandidates,
      memberPeople,
      excludePeople,
      minScore: activeReviewMoreMinScore,
    });
  }

  function reviewMoreForManagedGroup(folder: PhotoFolder) {
    const memberPeople = folder.groupProfile?.memberPeople || folder.groupPeople || [];
    const memberPets = folder.groupProfile?.memberPets || folder.groupPets || [];
    if (memberPeople.length + memberPets.length < 1) return;
    const excludePeople = folder.groupProfile?.excludePeople || folder.excludePeople || [];
    const excludePets = folder.groupProfile?.excludePets || folder.excludePets || [];
    const fallbackCandidateIds = reviewCandidatesForManagedGroup(folder).map((candidate) => candidate.candidateId);
    void openSuggestedReviewMore(
      {
        personNames: memberPeople,
        excludePeople,
        memberPets,
        excludePets,
        statuses: ["pending", "uncertain"],
        minScore: activeReviewMoreMinScore,
      },
      `${folder.name} ${uiText("Review More")}`,
      "group",
      fallbackCandidateIds
    );
  }

  async function renameManagedPerson(folder: PhotoFolder) {
    const oldName = folder.name.trim();
    const newName = String(peopleManagementRenameDrafts[folder.id] ?? folder.name).trim();
    const oldKey = oldName.toLowerCase();
    const newKey = newName.toLowerCase();
    if (!oldName || !newName || oldKey === newKey) return;
    const mergeTarget = peopleManagementPeople.some((person) => person.name.trim().toLowerCase() === newKey && person.name.trim().toLowerCase() !== oldKey);
    if (!await confirmPhotoAction({
      title: mergeTarget ? uiText("Merge person") : uiText("Rename person"),
      message: mergeTarget
        ? `${uiText("Merge")} ${oldName} ${uiText("into")} ${newName}?`
        : `${uiText("Rename")} ${oldName} ${uiText("to")} ${newName}?`,
      confirmLabel: mergeTarget ? uiText("Merge") : uiText("Rename"),
      danger: false,
    })) return;
    setPersonRenameSaving(true);
    setPersonRenameError("");
    try {
      await renamePerson(oldName, newName, { confirm: false });
      const nextActiveId = activeId === folder.id ? `person:${newName}` : activeId;
      if (nextActiveId !== activeId) setActiveId(nextActiveId);
      await loadFolders();
      await loadPeopleManagementFolders();
      await loadSuggestions();
      await loadDuplicatePeople();
      await loadPhotoOperations();
      await loadPage(nextActiveId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
    } catch (error) {
      setPersonRenameError(error instanceof Error ? error.message : String(error));
    } finally {
      setPersonRenameSaving(false);
    }
  }

