  async function renamePetFolder(folder: PhotoFolder, nextName: string) {
    const oldName = (folder.petName || folder.name || "").replace(/\s+/g, " ").trim();
    const newName = nextName.replace(/\s+/g, " ").trim();
    const oldKey = oldName.toLowerCase();
    const newKey = newName.toLowerCase();
    if (!oldName || !newName || oldKey === newKey) return;
    const petOptions = [
      ...peopleManagementPets,
      ...folders.filter((candidate) => candidate.kind === "pet"),
    ];
    const mergeTarget = petOptions.some((pet) => (pet.petName || pet.name).trim().toLowerCase() === newKey && (pet.petName || pet.name).trim().toLowerCase() !== oldKey);
    if (!await confirmPhotoAction({
      title: mergeTarget ? uiText("Merge pet") : uiText("Rename pet"),
      message: mergeTarget
        ? `${uiText("Merge")} ${oldName} ${uiText("into")} ${newName}?`
        : `${uiText("Rename")} ${oldName} ${uiText("to")} ${newName}?`,
      confirmLabel: mergeTarget ? uiText("Merge") : uiText("Rename"),
      danger: false,
    })) return;
    setPetSaving(true);
    setPetError("");
    try {
      await renamePhotoPet({ oldName, newName });
      const nextActiveId = `pet:${encodeURIComponent(newName)}`;
      if (activeId === folder.id) {
        setActiveId(nextActiveId);
        setPetRenameDraft(newName);
        await loadPage(nextActiveId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
      }
      setPetManagementRenameDrafts((current) => {
        const next = { ...current };
        delete next[folder.id];
        return next;
      });
      await loadFolders();
      if (peopleManagementOpen) await loadPeopleManagementFolders();
      await loadSuggestions();
    } catch (error) {
      setPetError(error instanceof Error ? error.message : String(error));
    } finally {
      setPetSaving(false);
    }
  }

