  async function assignSelectedPetReviewItems() {
    const petName = bulkPetAssignDraft.replace(/\s+/g, " ").trim();
    if (!selectedItems.length || !petName) {
      setPetError(uiText("Pet name is required."));
      return;
    }
    setPetSaving(true);
    setPetError("");
    let assigned = 0;
    let failed = 0;
    try {
      for (const item of selectedItems) {
        try {
          await assignPhotoPet({
            assetId: item.assetId || "",
            sourcePath: item.sourcePath,
            petName,
          });
          assigned += 1;
        } catch {
          failed += 1;
        }
      }
      if (assigned) {
        setBulkPetAssignDraft("");
        setPetAssignDraft(petName);
        setSelectedSources(new Set());
      }
      await loadFolders();
      if (peopleManagementOpen) await loadPeopleManagementFolders();
      await loadSuggestions();
      await loadPage(
        activeId,
        0,
        sort,
        searchQuery,
        keywordFilter,
        mediaKindFilter,
        favoriteOnly,
        editedOnly,
        notInAlbumOnly,
        personFilter,
        statusFilter,
        minQualityFilter,
        dateFromFilter,
        dateToFilter,
        sourceFilter,
        fileTypeFilter,
        duplicateOnly,
        locationFilter,
        cameraFilter,
        albumFilter,
        visibilityFilter,
        photoDateViewMode,
        activeDateBucketKey,
        groupViewMode,
        nearbyFilter
      );
      if (failed) {
        setPetError(`${uiText("Assigned")} ${formatCount(assigned)}; ${uiText("failed")} ${formatCount(failed)}.`);
      }
    } catch (error) {
      setPetError(error instanceof Error ? error.message : String(error));
    } finally {
      setPetSaving(false);
    }
  }

  async function dismissSelectedPetReviewItems() {
    if (!selectedItems.length) {
      setPetError(uiText("Select Pet Review photos first."));
      return;
    }
    setPetSaving(true);
    setPetError("");
    let dismissed = 0;
    let failed = 0;
    try {
      for (const item of selectedItems) {
        try {
          await dismissPhotoPetReview({
            assetId: item.assetId || "",
            sourcePath: item.sourcePath,
            petKind: petReviewKindFilter || "",
          });
          dismissed += 1;
        } catch {
          failed += 1;
        }
      }
      if (dismissed) {
        setSelectedSources(new Set());
      }
      await loadFolders();
      if (peopleManagementOpen) await loadPeopleManagementFolders();
      await loadSuggestions();
      await loadPage(
        activeId,
        0,
        sort,
        searchQuery,
        keywordFilter,
        mediaKindFilter,
        favoriteOnly,
        editedOnly,
        notInAlbumOnly,
        personFilter,
        statusFilter,
        minQualityFilter,
        dateFromFilter,
        dateToFilter,
        sourceFilter,
        fileTypeFilter,
        duplicateOnly,
        locationFilter,
        cameraFilter,
        albumFilter,
        visibilityFilter,
        photoDateViewMode,
        activeDateBucketKey,
        groupViewMode,
        nearbyFilter
      );
      setPetError(
        failed
          ? `${uiText("Dismissed")} ${formatCount(dismissed)}; ${uiText("failed")} ${formatCount(failed)}.`
          : `${uiText("Dismissed")} ${formatCount(dismissed)} ${dismissed === 1 ? uiText("pet review item") : uiText("pet review items")}.`
      );
    } catch (error) {
      setPetError(error instanceof Error ? error.message : String(error));
    } finally {
      setPetSaving(false);
    }
  }

