  async function saveActivePeopleGroup(patch: Record<string, unknown> = {}, options: { closeAfterSave?: boolean } = {}) {
    if (!activeGroup) return null;
    const name = groupNameDraft.trim() || activeGroup.name;
    const memberPeople = parsePhotoPeopleDraft(groupPeopleDraft);
    const excludePeople = parsePhotoPeopleDraft(groupExcludePeopleDraft);
    const memberPets = parsePhotoPeopleDraft(groupPetsDraft);
    const excludePets = parsePhotoPeopleDraft(groupExcludePetsDraft);
    if (!name) {
      setGroupError(uiText("Group name is required."));
      return null;
    }
    if (memberPeople.length + memberPets.length < 2) {
      setGroupError(uiText("Choose at least two people or pets for this group."));
      return null;
    }
    setGroupSaving(true);
    setGroupError("");
    try {
      const payload: Record<string, unknown> = {
        name,
        memberPeople,
        excludePeople,
        memberPets,
        excludePets,
        ...patch,
      };
      if (activeGroupId) payload.groupId = activeGroupId;
      const result = await savePhotoPeopleGroup(payload);
      const value = result.value && typeof result.value === "object" ? result.value as { groupId?: unknown } : {};
      const savedGroupId = String(value.groupId || activeGroupId || "");
      const nextActiveId = options.closeAfterSave ? "all" : (savedGroupId ? `group:saved:${savedGroupId}` : activeId);
      setActiveId(nextActiveId);
      await loadFolders();
      await loadPage(nextActiveId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
      return value;
    } catch (error) {
      setGroupError(error instanceof Error ? error.message : String(error));
      return null;
    } finally {
      setGroupSaving(false);
    }
  }

  async function deleteActivePeopleGroup() {
    if (!activeGroupId) return;
    if (!await confirmPhotoAction({
      title: uiText("Delete people group"),
      message: `${uiText("Delete")} ${activeGroup?.name || uiText("this people group")}?`,
      confirmLabel: uiText("Delete"),
      danger: true,
    })) return;
    setGroupSaving(true);
    setGroupError("");
    try {
      await deletePhotoPeopleGroup({ groupId: activeGroupId });
      setActiveId("all");
      await loadFolders();
      await loadPage("all", 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
    } catch (error) {
      setGroupError(error instanceof Error ? error.message : String(error));
    } finally {
      setGroupSaving(false);
    }
  }

  async function toggleFavoriteActiveGroup() {
    const favorite = !Boolean(activeGroup?.groupProfile?.favorite);
    await saveActivePeopleGroup({ favorite });
  }

  async function hideActiveGroup() {
    await saveActivePeopleGroup({ hidden: true }, { closeAfterSave: true });
  }

  async function clearActiveGroupCover() {
    if (!activeGroup) return;
    await saveActivePeopleGroup({ keyAssetId: "" });
  }

  async function setActiveGroupCover(item: PhotoItem) {
    if (!activeGroup || !item.assetId) return;
    await saveActivePeopleGroup({ keyAssetId: item.assetId });
  }

  function patchItemMetadata(sourcePath: string, patch: Partial<PhotoItem>) {
    setItems((current) => current.map((item) => item.sourcePath === sourcePath ? { ...item, ...patch } : item));
  }

  function patchItemMediaPair(target: PhotoItem, pair: PhotoMediaPair) {
    setItems((current) => current.map((item) => {
      const sameAsset = Boolean(target.assetId && item.assetId && target.assetId === item.assetId);
      const sameSource = Boolean(target.sourcePath && item.sourcePath === target.sourcePath);
      if (!sameAsset && !sameSource) return item;
      const pairs = normalizePhotoMediaPairList(item.mediaPairs);
      let replaced = false;
      const nextPairs = pairs.map((currentPair) => {
        if (currentPair.pairId && pair.pairId && currentPair.pairId === pair.pairId) {
          replaced = true;
          return { ...currentPair, ...pair };
        }
        return currentPair;
      });
      if (!replaced) nextPairs.push(pair);
      return { ...item, mediaPairs: nextPairs };
    }));
  }

  function removeItemMediaPair(target: PhotoItem, pairId: string) {
    setItems((current) => current.map((item) => {
      const sameAsset = Boolean(target.assetId && item.assetId && target.assetId === item.assetId);
      const sameSource = Boolean(target.sourcePath && item.sourcePath === target.sourcePath);
      if (!sameAsset && !sameSource) return item;
      const nextPairs = normalizePhotoMediaPairList(item.mediaPairs).filter((pair) => pair.pairId !== pairId);
      return { ...item, mediaPairs: nextPairs };
    }));
  }

  async function createLightboxPhotoMediaPair(item: PhotoItem) {
    if (!item.assetId) {
      setPhotoMediaPairRelinkError(uiText("This photo must be imported before adding related media."));
      return;
    }
    const paths = await chooseImportFiles();
    const relatedSourcePath = String(paths[0] || "").trim();
    if (!relatedSourcePath) return;
    setPhotoMediaPairCreating(true);
    setPhotoMediaPairRelinkError("");
    setPhotoMediaPairRelinkStatus("");
    try {
      const result = (await createPhotoMediaPair({
        assetId: item.assetId,
        pairKind: photoMediaPairDraftKind,
        relatedSourcePath,
      })).value;
      const updatedPair = normalizePhotoMediaPairList([result.pair])[0];
      if (updatedPair) {
        patchItemMediaPair(item, updatedPair);
      }
      setPhotoMediaPairRelinkStatus(result.created ? uiText("Related media added.") : uiText("Related media updated."));
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoMediaPairRelinkError(errorMessage(error));
    } finally {
      setPhotoMediaPairCreating(false);
    }
  }

  async function relinkLightboxPhotoMediaPair(item: PhotoItem, pair: PhotoMediaPair) {
    const pairId = String(pair.pairId || "").trim();
    if (!pairId) {
      setPhotoMediaPairRelinkError(uiText("This related-media row cannot be relinked."));
      return;
    }
    const paths = await chooseImportFiles();
    const relatedSourcePath = String(paths[0] || "").trim();
    if (!relatedSourcePath) return;
    setPhotoMediaPairRelinkingId(pairId);
    setPhotoMediaPairRelinkError("");
    setPhotoMediaPairRelinkStatus("");
    try {
      const result = (await relinkPhotoMediaPair({
        pairId,
        assetId: item.assetId || pair.assetId || "",
        relatedSourcePath,
      })).value;
      const updatedPair = normalizePhotoMediaPairList([result.pair])[0];
      if (updatedPair) {
        patchItemMediaPair(item, updatedPair);
      }
      setPhotoMediaPairRelinkStatus(uiText("Related media relinked."));
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoMediaPairRelinkError(errorMessage(error));
    } finally {
      setPhotoMediaPairRelinkingId("");
    }
  }

  async function deleteLightboxPhotoMediaPair(item: PhotoItem, pair: PhotoMediaPair, suppressGenerated = false) {
    const pairId = String(pair.pairId || "").trim();
    const canRemove = photoMediaPairCanRemove(pair);
    const canIgnore = suppressGenerated && photoMediaPairCanIgnoreGenerated(pair);
    if (!pairId || (!canRemove && !canIgnore)) {
      setPhotoMediaPairRelinkError(uiText("Only manually added/relinked related media can be removed, and generated rows must be ignored explicitly."));
      return;
    }
    const actionLabel = suppressGenerated ? uiText("Ignore") : uiText("Remove");
    if (!await confirmPhotoAction({
      title: suppressGenerated ? uiText("Ignore generated related media") : uiText("Remove related media"),
      message: `${actionLabel} ${uiText(photoMediaPairKindLabel(pair.pairKind))} ${photoMediaPairFilename(pair) || uiText("related media")} ${suppressGenerated ? uiText("for this photo? Future scans will not recreate this generated row.") : uiText("from this photo? The file will stay on disk.")}`,
      confirmLabel: actionLabel,
      danger: false,
    })) return;
    setPhotoMediaPairDeletingId(pairId);
    setPhotoMediaPairRelinkError("");
    setPhotoMediaPairRelinkStatus("");
    try {
      await deletePhotoMediaPair({
        pairId,
        assetId: item.assetId || pair.assetId || "",
        suppressGenerated,
      });
      removeItemMediaPair(item, pairId);
      setPhotoMediaPairRelinkStatus(suppressGenerated ? uiText("Generated related media ignored.") : uiText("Related media removed."));
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoMediaPairRelinkError(errorMessage(error));
    } finally {
      setPhotoMediaPairDeletingId("");
    }
  }

  function photoContextMenuPosition(x: number, y: number) {
    if (typeof window === "undefined") return { x, y };
    const menuWidth = 244;
    const menuHeight = 360;
    return {
      x: Math.max(12, Math.min(x, window.innerWidth - menuWidth - 12)),
      y: Math.max(12, Math.min(y, window.innerHeight - menuHeight - 12)),
    };
  }

  function openPhotoItemContextMenu(event: ReactMouseEvent<HTMLElement>, item: PhotoItem, itemIndex: number) {
    event.preventDefault();
    event.stopPropagation();
    const point = photoContextMenuPosition(event.clientX, event.clientY);
    setPhotoContextMenu({ kind: "photo", sourcePath: item.sourcePath, itemIndex, ...point });
  }

  function openPhotoItemContextMenuFromButton(event: ReactMouseEvent<HTMLElement>, item: PhotoItem, itemIndex: number) {
    event.preventDefault();
    event.stopPropagation();
    const rect = event.currentTarget.getBoundingClientRect();
    const point = photoContextMenuPosition(rect.right - 8, rect.bottom + 6);
    setPhotoContextMenu({ kind: "photo", sourcePath: item.sourcePath, itemIndex, ...point });
  }

