  function closePhotoContextMenu() {
    setPhotoContextMenu(null);
  }

  function resolvePhotoConfirmation(confirmed: boolean) {
    const resolver = photoConfirmationResolverRef.current;
    photoConfirmationResolverRef.current = null;
    setPhotoConfirmation(null);
    if (resolver) resolver(confirmed);
  }

  function confirmPhotoAction(options: Partial<PhotoConfirmationState> & Pick<PhotoConfirmationState, "message">): Promise<boolean> {
    if (photoConfirmationResolverRef.current) {
      photoConfirmationResolverRef.current(false);
      photoConfirmationResolverRef.current = null;
    }
    setPhotoConfirmation({
      title: options.title || uiText("Confirm action"),
      message: options.message,
      confirmLabel: options.confirmLabel || uiText("Confirm"),
      cancelLabel: options.cancelLabel || uiText("Cancel"),
      danger: options.danger ?? true,
    });
    return new Promise((resolve) => {
      photoConfirmationResolverRef.current = resolve;
    });
  }

  useEffect(() => {
    if (!photoConfirmation) return undefined;
    const frame = window.requestAnimationFrame(() => photoConfirmationConfirmRef.current?.focus());
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        resolvePhotoConfirmation(false);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => {
      window.cancelAnimationFrame(frame);
      window.removeEventListener("keydown", onKey);
    };
  }, [photoConfirmation]);

  useEffect(() => () => {
    if (photoConfirmationResolverRef.current) {
      photoConfirmationResolverRef.current(false);
      photoConfirmationResolverRef.current = null;
    }
  }, []);

  useEffect(() => {
    if (!photoContextMenu) return undefined;
    const close = () => closePhotoContextMenu();
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        closePhotoContextMenu();
      }
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("resize", close);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("resize", close);
    };
  }, [photoContextMenu]);

  type PhotoMetadataPatch = Partial<Pick<PhotoItem, "title" | "caption" | "keywords" | "favorite" | "hidden" | "deletedAt" | "dateOverride" | "locationOverride" | "locationHidden">> & {
    accessibilityDescription?: string;
    captureDate?: string;
    descriptionRegions?: Array<Record<string, unknown>>;
    objectTagReview?: Record<string, unknown>;
    utilityClassifierReview?: Record<string, unknown>;
    localDepthControls?: Record<string, unknown> | null;
  };

  async function savePhotoMetadata(item: PhotoItem, patch: PhotoMetadataPatch) {
    setSavingMetadata(true);
    setMetadataError("");
    try {
      const result = await updatePhotoAssetMetadata({
        sourcePath: item.sourcePath,
        assetId: item.assetId || "",
        ...patch,
      });
      const value = result.value || {};
      const valueAssetMetadata = value.assetMetadata && typeof value.assetMetadata === "object" ? value.assetMetadata as Record<string, unknown> : {};
      const nextAssetMetadata = {
        ...(item.assetMetadata || {}),
        ...valueAssetMetadata,
      };
      if ("accessibilityDescription" in patch) {
        const description = String(value.accessibilityDescription ?? patch.accessibilityDescription ?? "").replace(/\s+/g, " ").trim();
        if (description) {
          nextAssetMetadata.accessibilityDescription = description;
        } else {
          delete nextAssetMetadata.accessibilityDescription;
        }
      }
      if ("descriptionRegions" in patch) {
        const regions = serializePhotoDescriptionRegions(value.descriptionRegions ?? patch.descriptionRegions ?? []);
        if (regions.length) {
          nextAssetMetadata.descriptionRegions = regions;
        } else {
          delete nextAssetMetadata.descriptionRegions;
        }
      }
      if ("objectTagReview" in patch) {
        const review = (valueAssetMetadata.objectTagReview && typeof valueAssetMetadata.objectTagReview === "object")
          ? valueAssetMetadata.objectTagReview as Record<string, unknown>
          : patch.objectTagReview || {};
        const entries = Array.isArray(review.entries) ? review.entries : [];
        if (entries.length) {
          nextAssetMetadata.objectTagReview = review;
        } else {
          delete nextAssetMetadata.objectTagReview;
        }
      }
      if ("utilityClassifierReview" in patch) {
        const review = (valueAssetMetadata.utilityClassifierReview && typeof valueAssetMetadata.utilityClassifierReview === "object")
          ? valueAssetMetadata.utilityClassifierReview as Record<string, unknown>
          : patch.utilityClassifierReview || {};
        const entries = Array.isArray(review.entries) ? review.entries : [];
        if (entries.length) {
          nextAssetMetadata.utilityClassifierReview = review;
        } else {
          delete nextAssetMetadata.utilityClassifierReview;
        }
      }
      if ("localDepthControls" in patch) {
        const controls = valueAssetMetadata.localDepthControls && typeof valueAssetMetadata.localDepthControls === "object"
          ? valueAssetMetadata.localDepthControls as Record<string, unknown>
          : patch.localDepthControls || {};
        if (controls && Object.keys(controls).length) {
          nextAssetMetadata.localDepthControls = controls;
        } else {
          delete nextAssetMetadata.localDepthControls;
        }
      }
      const nextPatch: Partial<PhotoItem> = {
        assetId: String(value.assetId || item.assetId || ""),
        title: String(value.title ?? patch.title ?? item.title ?? ""),
        caption: String(value.caption ?? patch.caption ?? item.caption ?? ""),
        keywords: Array.isArray(value.keywords)
          ? value.keywords.map((keyword) => String(keyword)).filter(Boolean)
          : patch.keywords ?? item.keywords ?? [],
        favorite: Boolean(value.favorite ?? patch.favorite ?? item.favorite ?? false),
        hidden: Boolean(value.hidden ?? patch.hidden ?? item.hidden ?? false),
        deletedAt: String(value.deletedAt ?? patch.deletedAt ?? item.deletedAt ?? ""),
        dateOverride: String(value.dateOverride ?? patch.dateOverride ?? item.dateOverride ?? ""),
        locationOverride: (value.locationOverride && typeof value.locationOverride === "object" ? value.locationOverride : patch.locationOverride ?? item.locationOverride ?? {}) as Record<string, unknown>,
        locationHidden: Boolean(value.locationHidden ?? patch.locationHidden ?? item.locationHidden ?? false),
        assetMetadata: nextAssetMetadata,
      };
      if ("captureDate" in patch) {
        const originalCaptureDate = String(value.captureDate ?? patch.captureDate ?? item.originalCaptureDate ?? "");
        nextPatch.originalCaptureDate = originalCaptureDate;
        if (!nextPatch.dateOverride) nextPatch.captureDate = originalCaptureDate;
      }
      if ("dateOverride" in patch) {
        const mergedItem = {
          ...item,
          originalCaptureDate: String(nextPatch.originalCaptureDate ?? item.originalCaptureDate ?? ""),
        };
        nextPatch.captureDate = restoredPhotoCaptureDate(mergedItem, nextPatch.dateOverride || "");
      }
      patchItemMetadata(item.sourcePath, nextPatch);
      await loadPhotoOperations();
      return nextPatch;
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
      return null;
    } finally {
      setSavingMetadata(false);
    }
  }

  function photoXmpConflictCleanText(value: unknown): string {
    return String(value ?? "").replace(/\s+/g, " ").trim();
  }

  function photoXmpConflictPatch(conflict: PhotoXmpMetadataConflict): PhotoMetadataPatch | null {
    const sidecarText = photoXmpConflictCleanText(conflict.sidecarValue ?? conflict.sidecar);
    if (conflict.field === "title") return { title: sidecarText };
    if (conflict.field === "caption") return { caption: sidecarText };
    if (conflict.field === "dateOverride") return sidecarText ? { dateOverride: sidecarText } : null;
    if (conflict.field === "keywords") {
      const rawKeywords = Array.isArray(conflict.sidecarValue)
        ? conflict.sidecarValue
        : String(conflict.sidecar || "").split(",");
      const keywords = rawKeywords
        .map((keyword) => photoXmpConflictCleanText(keyword))
        .filter(Boolean);
      return keywords.length ? { keywords } : null;
    }
    if (conflict.field === "locationOverride") {
      const value = conflict.sidecarValue;
      const record = value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
      const locationOverride: Record<string, unknown> = {};
      const label = photoXmpConflictCleanText(record.label);
      const latitude = photoXmpConflictCleanText(record.latitude);
      const longitude = photoXmpConflictCleanText(record.longitude);
      if (label) locationOverride.label = label;
      if (latitude) locationOverride.latitude = latitude;
      if (longitude) locationOverride.longitude = longitude;
      return Object.keys(locationOverride).length ? { locationOverride, locationHidden: false } : null;
    }
    return null;
  }

  async function usePhotoXmpConflict(item: PhotoItem, conflict: PhotoXmpMetadataConflict) {
    const patch = photoXmpConflictPatch(conflict);
    if (!patch) return;
    const dateChanged = "dateOverride" in patch && normalizePhotoDateTimeOverride(String(patch.dateOverride || "")) !== normalizePhotoDateTimeOverride(item.dateOverride || "");
    const folderSensitive = dateChanged || "locationOverride" in patch || "locationHidden" in patch || "keywords" in patch;
    const saved = await savePhotoMetadata(item, patch);
    if (!saved) return;
    if ("title" in patch) setTitleDraft(String(saved.title || ""));
    if ("caption" in patch) setCaptionDraft(String(saved.caption || ""));
    if ("keywords" in patch) {
      setKeywordsDraft((saved.keywords || []).join(", "));
      await loadKeywords();
    }
    if ("dateOverride" in patch) {
      const dateTime = splitPhotoDateTimeOverride(saved.dateOverride || "");
      setDateDraft(dateTime.date);
      setTimeDraft(dateTime.time);
      setTimezoneDraft(dateTime.timezone);
      setDateBucketRefreshToken((token) => token + 1);
    }
    if ("locationOverride" in patch || "locationHidden" in patch) {
      setLocationLabelDraft(String(saved.locationOverride?.label || ""));
      setLocationLatitudeDraft(String(saved.locationOverride?.latitude || ""));
      setLocationLongitudeDraft(String(saved.locationOverride?.longitude || ""));
      setLocationHiddenDraft(Boolean(saved.locationHidden));
    }
    if (folderSensitive) await loadFolders();
  }

  async function toggleFavorite(item: PhotoItem) {
    await savePhotoMetadata(item, { favorite: !item.favorite });
    await loadFolders();
  }

  async function refreshAfterVisibilityChange() {
    setSelectedSources(new Set());
    setLightbox(null);
    await loadFolders();
    await loadSuggestions();
    await loadPhotoOperations();
    await loadPage(activeId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
  }

  async function rebuildVisiblePhotoPreviews() {
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    const paths = items
      .map((item) => String(item.sourcePath || "").trim())
      .filter(Boolean);
    if (!paths.length) {
      setPreviewRepairError(uiText("No loaded photos to rebuild."));
      return;
    }
    setPreviewRepairing(true);
    setPreviewRepairError("");
    setPreviewRepairStatus("");
    try {
      const result = (await rebuildPhotoPreviews({
        sourcePaths: paths,
        limit: Math.max(PAGE_LIMIT, paths.length),
        force: true,
        libraryRoot,
        libraryRootProfileId,
      })).value;
      const generated = Number(result.generatedPreviews || 0);
      const failed = Array.isArray(result.failed) ? result.failed.length : 0;
      const skipped = Array.isArray(result.skipped) ? result.skipped.length : 0;
      setPreviewRepairStatus(`${uiText("Rebuilt")} ${generated} preview${generated === 1 ? "" : "s"}.${failed || skipped ? ` ${failed + skipped} item${failed + skipped === 1 ? "" : "s"} still need attention.` : ""}`);
      setPreviewLoadWarning("");
      await loadPhotoRepairHistory();
      await loadPage(activeId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
    } catch (error) {
      setPreviewRepairError(errorMessage(error));
    } finally {
      setPreviewRepairing(false);
    }
  }

  async function rebuildMissingPhotoPreviews() {
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    const paths = (photoBackupCheck?.samples?.missingCachedPreviews || [])
      .map((sample) => String(sample.sourcePath || "").trim())
      .filter(Boolean);
    if (!paths.length) {
      await rebuildVisiblePhotoPreviews();
      return;
    }
    setPreviewRepairing(true);
    setPreviewRepairError("");
    setPreviewRepairStatus("");
    try {
      const result = (await rebuildPhotoPreviews({
        sourcePaths: paths,
        limit: Math.max(PAGE_LIMIT, paths.length),
        force: true,
        libraryRoot,
        libraryRootProfileId,
      })).value;
      const generated = Number(result.generatedPreviews || 0);
      const failed = Array.isArray(result.failed) ? result.failed.length : 0;
      const skipped = Array.isArray(result.skipped) ? result.skipped.length : 0;
      setPreviewRepairStatus(`${uiText("Rebuilt")} ${generated} preview${generated === 1 ? "" : "s"} from repair scan.${failed || skipped ? ` ${failed + skipped} item${failed + skipped === 1 ? "" : "s"} still need attention.` : ""}`);
      setPreviewLoadWarning("");
      const check = await photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot, libraryRootProfileId });
      setPhotoBackupCheck(check.value || null);
      await loadPhotoRepairHistory();
      await loadPage(activeId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
    } catch (error) {
      setPreviewRepairError(errorMessage(error));
    } finally {
      setPreviewRepairing(false);
    }
  }

  async function runPhotoPreviewSweep() {
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    if (!(await confirmPhotoAction({
      title: uiText("Sweep previews"),
      message: uiText("Generate missing cached previews across the local Photos library? This may take a moment on larger libraries."),
      confirmLabel: uiText("Sweep previews"),
      danger: false,
    }))) return;
    setPhotoPreviewSweeping(true);
    setPreviewRepairError("");
    setPreviewRepairStatus("");
    try {
      const sweep = (await photoLibraryPreviewSweep({
        missingOnly: true,
        force: false,
        limit: 1000,
        sampleLimit: 8,
        libraryRoot,
        libraryRootProfileId,
      })).value;
      const generated = Number(sweep?.counts?.generatedPreviews || 0);
      const remaining = Number(sweep?.counts?.remainingMissingCachedPreviews || 0);
      const failed = Number(sweep?.counts?.failedPreviews || 0);
      setPreviewRepairStatus(remaining || failed
        ? `${uiText("Generated")} ${formatCount(generated)} preview${generated === 1 ? "" : "s"}; ${formatCount(remaining + failed)} ${uiText("still need attention")}.`
        : `${uiText("Generated")} ${formatCount(generated)} preview${generated === 1 ? "" : "s"} across the library.`);
      setPreviewLoadWarning("");
      const check = await photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot });
      setPhotoBackupCheck(check.value || null);
      await loadPhotoRepairHistory();
      await loadPage(activeId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
    } catch (error) {
      setPreviewRepairError(errorMessage(error));
      setPhotoRepairError(errorMessage(error));
    } finally {
      setPhotoPreviewSweeping(false);
    }
  }

  async function relinkPhotoOriginals(sourcePath?: string | null) {
    const source = String(sourcePath || missingOriginalSamplePath || "").trim();
    if (!source) {
      setPhotoRelinkError(uiText("Choose a missing photo first."));
      return;
    }
    const oldRoot = parentFolder(source);
    if (!oldRoot || oldRoot === source) {
      setPhotoRelinkError(uiText("Could not infer the missing photo folder."));
      return;
    }
    const newRoot = await chooseImportFolder();
    if (!newRoot) return;
    setPhotoRelinking(true);
    setPhotoRelinkError("");
    setPhotoRelinkStatus("");
    try {
      const preview = (await relinkPhotoLibraryPaths({ oldRoot, newRoot, dryRun: true })).value;
      const relinkable = Number(preview.relinkedAssets || 0);
      const matched = Number(preview.matchedAssets || 0);
      const skipped = Number(preview.missingTargets.length + preview.conflicts.length);
      if (!matched) {
        setPhotoRelinkStatus(uiText("No Photos originals matched that missing folder."));
        return;
      }
      if (!relinkable) {
        setPhotoRelinkStatus(uiText("No replacement originals were found in the selected folder."));
        return;
      }
      const skippedText = skipped
        ? ` ${skipped} matched item${skipped === 1 ? "" : "s"} will stay missing because the replacement file was not found or already belongs to another asset.`
        : "";
      if (!await confirmPhotoAction({
        title: uiText("Relink originals"),
        message: `${uiText("Relink")} ${relinkable} Photos original${relinkable === 1 ? "" : "s"} from ${fileName(oldRoot) || oldRoot} to ${fileName(newRoot) || newRoot}?${skippedText}`,
        confirmLabel: uiText("Relink"),
        danger: false,
      })) return;
      const result = (await relinkPhotoLibraryPaths({
        oldRoot,
        newRoot,
        dryRun: false,
        forcePartial: skipped > 0,
      })).value;
      if (result.partialBlocked) {
        setPhotoRelinkError(uiText("Relink was blocked because some replacement files are missing."));
        return;
      }
      setPhotoRelinkStatus(`${uiText("Relinked")} ${result.relinkedAssets} Photos original${result.relinkedAssets === 1 ? "" : "s"}.`);
      await loadPhotoRepairHistory();
      await refreshAfterVisibilityChange();
    } catch (error) {
      setPhotoRelinkError(errorMessage(error));
    } finally {
      setPhotoRelinking(false);
    }
  }

  async function consolidatePhotoOriginals(sourcePaths: string[] = selectedConsolidatableSources) {
    const paths = sourcePaths.map((path) => String(path || "").trim()).filter(Boolean);
    if (!paths.length) {
      setPhotoConsolidationError(uiText("Choose referenced originals to consolidate."));
      return;
    }
    const managedRoot = configuredManagedRoot || await chooseDestinationFolder();
    if (!managedRoot) return;
    setPhotoConsolidating(true);
    setPhotoConsolidationError("");
    setPhotoConsolidationStatus("");
    setLastPhotoConsolidationResult(null);
    try {
      const preview = (await consolidatePhotoLibraryAssets({
        sourcePaths: paths,
        managedRoot,
        dryRun: true,
      })).value;
      const count = Number(preview.consolidatedAssets || 0);
      const skipped = Number(preview.skippedAssets || 0);
      if (!count) {
        setPhotoConsolidationStatus(uiText("No referenced originals need consolidation."));
        setLastPhotoConsolidationResult(preview);
        return;
      }
      const skippedText = skipped
        ? ` ${skipped} selected item${skipped === 1 ? "" : "s"} will be skipped because they are already managed, missing, deleted, or unavailable.`
        : "";
      if (!await confirmPhotoAction({
        title: uiText("Consolidate originals"),
        message: `${uiText("Copy")} ${count} referenced original${count === 1 ? "" : "s"} into the selected managed folder and update the library to use the managed copies? Referenced originals stay on disk.${skippedText}`,
        confirmLabel: uiText("Consolidate"),
        danger: false,
      })) return;
      const result = (await consolidatePhotoLibraryAssets({
        sourcePaths: paths,
        managedRoot,
        dryRun: false,
      })).value;
      setPhotoConsolidationStatus(`${uiText("Consolidated")} ${result.consolidatedAssets} Photos original${result.consolidatedAssets === 1 ? "" : "s"}.`);
      setLastPhotoConsolidationResult(result);
      await loadPhotoRepairHistory();
      await refreshAfterVisibilityChange();
    } catch (error) {
      setPhotoConsolidationError(errorMessage(error));
      setLastPhotoConsolidationResult(null);
    } finally {
      setPhotoConsolidating(false);
    }
  }

  function renderPhotoConsolidationResult(summary: PhotoConsolidationSummary | null = photoConsolidationSummary): ReactNode {
    if (photoConsolidationError) {
      return (
        <section className="photo-consolidation-result warning" aria-label={uiText("Consolidation result")} aria-live="polite">
          <div className="photo-consolidation-result-head">
            <span>
              <strong>{uiText("Consolidation failed")}</strong>
              <small>{photoConsolidationError}</small>
            </span>
          </div>
        </section>
      );
    }
    if (!summary) return photoConsolidationStatus ? <small>{photoConsolidationStatus}</small> : null;
    const resultClass = summary.status === "warning" ? "warning" : summary.status === "ok" ? "ok" : "empty";
    return (
      <section className={`photo-consolidation-result ${resultClass}`} aria-label={uiText("Consolidation result")} aria-live="polite">
        <div className="photo-consolidation-result-head">
          <span>
            <strong>{uiText(summary.title)}</strong>
            <small>{uiText(summary.detail)}</small>
          </span>
          {summary.status === "warning" ? <AlertTriangle size={15} /> : <Check size={15} />}
        </div>
        <div className="photo-consolidation-result-metrics">
          {summary.metrics.map((metric) => (
            <span key={metric.key}>{uiText(metric.label)}: {metric.value}</span>
          ))}
        </div>
        {summary.managedRootLabel && (
          <small>
            {uiText("Managed folder")}: <span title={summary.managedRootPath}>{summary.managedRootLabel}</span>
          </small>
        )}
        {summary.rows.length > 0 && (
          <div className="photo-consolidation-result-rows">
            {summary.rows.map((row) => (
              <div className="photo-consolidation-result-row" key={row.key}>
                <strong>{uiText(row.label)}</strong>
                <span>{row.sourceName}</span>
                <small>{row.detail}</small>
              </div>
            ))}
          </div>
        )}
        {summary.hiddenRowCount > 0 && (
          <small>{formatCount(summary.hiddenRowCount)} {summary.hiddenRowCount === 1 ? uiText("more item") : uiText("more items")}</small>
        )}
      </section>
    );
  }

  function renderPhotoConsolidationHistory(rows: PhotoConsolidationHistoryRow[] = photoConsolidationHistoryRows): ReactNode {
    if (!rows.length) return null;
    return (
      <section className="photo-consolidation-history" aria-label={uiText("Recent consolidations")}>
        <div className="photo-consolidation-history-head">
          <Clock size={14} />
          <strong>{uiText("Recent consolidations")}</strong>
          <small>{formatCount(rows.length)}</small>
        </div>
        <div className="photo-consolidation-history-list">
          {rows.map((row) => (
            <article key={row.key} className={row.status === "warning" ? "photo-consolidation-history-row warn" : "photo-consolidation-history-row"}>
              <span>
                <strong>{uiText(row.title)}</strong>
                <small>{row.summary}</small>
              </span>
              <div className="photo-consolidation-history-metrics">
                <span>{uiText("Copied")}: {formatCount(row.originalsCopied)}</span>
                {row.stillReferenced > 0 && <span>{uiText("Still referenced")}: {formatCount(row.stillReferenced)}</span>}
                {row.companionsCopied > 0 && <span>{uiText("Companions")}: {formatCount(row.companionsCopied)}</span>}
                {row.undoAvailable && <span>{uiText("Undo available")}</span>}
              </div>
              {row.managedRootLabel && (
                <small>
                  {uiText("Managed folder")}: <span title={row.managedRootPath || row.managedRootLabel}>{row.managedRootLabel}</span>
                </small>
              )}
              {(row.copiedSamples || row.companionSamples || row.skippedSamples) && (
                <div className="photo-consolidation-history-samples">
                  {row.copiedSamples && <small>{uiText("Copied samples")}: {row.copiedSamples}</small>}
                  {row.companionSamples && <small>{uiText("Companion samples")}: {row.companionSamples}</small>}
                  {row.skippedSamples && <small>{uiText("Skipped samples")}: {row.skippedSamples}</small>}
                </div>
              )}
              {row.at && <small className="photo-consolidation-history-date">{formatDateText(row.at)}</small>}
            </article>
          ))}
        </div>
      </section>
    );
  }

  async function runPhotoLibraryBackupCheck() {
    const libraryRoot = activeLibraryRootRef.current;
    setPhotoBackupChecking(true);
    setPhotoBackupCheckError("");
    try {
      const result = await photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot });
      setPhotoBackupCheck(result.value || null);
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoBackupCheckError(errorMessage(error));
    } finally {
      setPhotoBackupChecking(false);
    }
  }

  async function loadPhotoRepairHistory() {
    try {
      const result = await photoRepairHistory({ limit: 8 });
      setPhotoRepairHistoryValue(result.value || null);
      setPhotoRepairHistoryError("");
    } catch (error) {
      setPhotoRepairHistoryError(errorMessage(error));
    }
  }

  function rootRepairKey(rootPath: string) {
    return sourceFolderKey(rootPath);
  }

  function setPhotoRootRepairState(rootPath: string, patch: Partial<PhotoRootRepairState>) {
    const key = rootRepairKey(rootPath);
    if (!key) return;
    setPhotoRootRepairStates((current) => ({
      ...current,
      [key]: {
        ...(current[key] || {}),
        ...patch,
      },
    }));
  }

  function setPhotoRootBusy(rootPath: string, busyAction: PhotoRootRepairAction | "") {
    setPhotoRootRepairState(rootPath, { busyAction, error: busyAction ? "" : undefined });
  }

  async function runManagedRootBackupCheck(rootPath: string, rootName: string) {
    const cleanRoot = String(rootPath || "").trim();
    if (!cleanRoot) return;
    setPhotoRootBusy(cleanRoot, "backup");
    try {
      const result = await photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot: cleanRoot });
      const value = result.value || null;
      const counts = value?.counts || {};
      setPhotoRootRepairState(cleanRoot, {
        busyAction: "",
        backupCheck: value,
        message: `${uiText("Checked")} ${rootName || fileName(cleanRoot) || uiText("root")}: ${formatCount(Number(counts.assets || 0))} ${uiText("assets")}, ${formatCount(Number(counts.missingOriginals || 0))} ${uiText("missing originals")}.`,
        error: "",
        updatedAt: value?.generatedAt || new Date().toISOString(),
      });
      if (activeLibraryRootRef.current === cleanRoot) {
        setPhotoBackupCheck(value);
        setPhotoBackupCheckError("");
      }
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRootRepairState(cleanRoot, { busyAction: "", error: errorMessage(error), updatedAt: new Date().toISOString() });
    }
  }

  async function runManagedRootPreviewSweep(rootPath: string, rootName: string) {
    const cleanRoot = String(rootPath || "").trim();
    if (!cleanRoot) return;
    if (!(await confirmPhotoAction({
      title: uiText("Sweep root previews"),
      message: `${uiText("Generate missing cached previews for")} ${rootName || fileName(cleanRoot) || uiText("this root")}?`,
      confirmLabel: uiText("Sweep previews"),
      danger: false,
    }))) return;
    setPhotoRootBusy(cleanRoot, "previewSweep");
    try {
      const result = await photoLibraryPreviewSweep({
        missingOnly: true,
        force: false,
        limit: 1000,
        sampleLimit: 8,
        libraryRoot: cleanRoot,
      });
      const value = result.value || null;
      const counts = value?.counts || {};
      setPhotoRootRepairState(cleanRoot, {
        busyAction: "",
        previewSweep: value,
        message: `${uiText("Preview sweep")} ${rootName || fileName(cleanRoot) || uiText("root")}: ${formatCount(Number(counts.generatedPreviews || 0))} ${uiText("generated")}, ${formatCount(Number(counts.remainingMissingCachedPreviews || 0))} ${uiText("remaining")}.`,
        error: "",
        updatedAt: value?.generatedAt || new Date().toISOString(),
      });
      if (activeLibraryRootRef.current === cleanRoot) {
        const check = await photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot: cleanRoot });
        setPhotoBackupCheck(check.value || null);
        setPhotoBackupCheckError("");
      }
      await loadPhotoRepairHistory();
      await loadPage(activeId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
    } catch (error) {
      setPhotoRootRepairState(cleanRoot, { busyAction: "", error: errorMessage(error), updatedAt: new Date().toISOString() });
    }
  }

  async function runManagedRootOrphanScan(rootPath: string, rootName: string, dryRun = true) {
    const cleanRoot = String(rootPath || "").trim();
    if (!cleanRoot) return;
    setPhotoRootBusy(cleanRoot, dryRun ? "orphanPreview" : "orphanScan");
    try {
      const result = await scanPhotoRecoveredOrphans({
        roots: [cleanRoot],
        libraryRoot: cleanRoot,
        limit: 500,
        dryRun,
      });
      const value = result.value || null;
      setPhotoRootRepairState(cleanRoot, {
        busyAction: "",
        orphanScan: value,
        message: dryRun
          ? `${uiText("Orphan preview")} ${rootName || fileName(cleanRoot) || uiText("root")}: ${formatCount(Number(value?.orphanCandidates || 0))} ${uiText("candidate(s)")}.`
          : `${uiText("Orphan scan")} ${rootName || fileName(cleanRoot) || uiText("root")}: ${formatCount(Number(value?.recorded || 0))} ${uiText("recorded")}.`,
        error: "",
        updatedAt: value?.generatedAt || new Date().toISOString(),
      });
      if (!dryRun) {
        await loadRecoveredFailures();
        await loadFolders();
      }
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRootRepairState(cleanRoot, { busyAction: "", error: errorMessage(error), updatedAt: new Date().toISOString() });
    }
  }

  async function previewPhotoCatalogCleanup() {
    setPhotoCatalogCleanupPreviewing(true);
    setPhotoRepairError("");
    try {
      const cleanup = (await photoLibraryCatalogCleanup({ apply: false, sampleLimit: 8 })).value;
      setPhotoCatalogCleanupPreview(cleanup || null);
      const candidates = Number(cleanup?.counts?.cleanupCandidates || 0);
      setPhotoRepairStatus(candidates > 0
        ? `${uiText("Cleanup preview found")} ${formatCount(candidates)} ${uiText("catalog row")}${candidates === 1 ? "" : "s"}.`
        : uiText("Cleanup preview found no catalog drift."));
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRepairError(errorMessage(error));
    } finally {
      setPhotoCatalogCleanupPreviewing(false);
    }
  }

  async function runPhotoCatalogCleanup() {
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    const previewCandidates = Number(photoCatalogCleanupPreview?.counts?.cleanupCandidates || 0);
    if (!photoCatalogCleanupPreview) {
      await previewPhotoCatalogCleanup();
      return;
    }
    if (previewCandidates <= 0) {
      setPhotoRepairStatus(uiText("Cleanup preview found no catalog drift."));
      return;
    }
    if (!(await confirmPhotoAction({
      title: uiText("Clean catalog"),
      message: `${uiText("Remove broken album, search, cover, and metadata rows that point at missing catalog records? Originals and valid photos will not be changed.")} ${formatCount(previewCandidates)} ${uiText("candidate row(s) will be checked.")}`,
      confirmLabel: uiText("Clean catalog"),
      danger: false,
    }))) return;
    setPhotoCatalogCleaning(true);
    setPhotoRepairError("");
    try {
      const cleanup = (await photoLibraryCatalogCleanup({ apply: true, sampleLimit: 8 })).value;
      const cleaned = Number(cleanup?.counts?.cleanedRows || 0);
      const remaining = Number(cleanup?.counts?.remainingCandidates || 0);
      setPhotoCatalogCleanupPreview(cleanup || null);
      const check = await photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot, libraryRootProfileId });
      setPhotoBackupCheck(check.value || null);
      setPhotoBackupCheckError("");
      setPhotoRepairStatus(remaining > 0
        ? `${uiText("Cleaned")} ${formatCount(cleaned)} ${uiText("catalog row")}${cleaned === 1 ? "" : "s"}; ${formatCount(remaining)} ${uiText("remain")}.`
        : `${uiText("Cleaned")} ${formatCount(cleaned)} ${uiText("catalog row")}${cleaned === 1 ? "" : "s"}.`);
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRepairError(errorMessage(error));
    } finally {
      setPhotoCatalogCleaning(false);
    }
  }

  async function runPhotoRestoreRehearsal() {
    setPhotoRestoreRehearsing(true);
    setPhotoRestoreRehearsalError("");
    try {
      const result = await photoRestoreRehearsal({ limit: 6 });
      setPhotoRestoreRehearsalValue(result.value || null);
      await loadPhotoRepairHistory();
      return result.value || null;
    } catch (error) {
      setPhotoRestoreRehearsalError(errorMessage(error));
      return null;
    } finally {
      setPhotoRestoreRehearsing(false);
    }
  }

  async function runPhotoBackupRestoreRehearsal(createBackup = true, scheduled = false) {
    setPhotoBackupRestoreRehearsing(true);
    setPhotoBackupRestoreRehearsalError("");
    try {
      const result = await props.photoBackupRestoreRehearsal({
        sampleLimit: 8,
        createBackup,
        includeGenerated: Boolean(photoLibraryProfile?.backupPolicy?.includeGenerated),
        scheduled,
        recordPolicy: true,
      });
      const value = result.value || null;
      setPhotoBackupRestoreRehearsalValue(value);
      if (value?.policyStatus) {
        setPhotoLibraryProfile((current) => current ? {
          ...current,
          backupPolicy: value.policyStatus?.policy || current.backupPolicy,
          backupPolicyStatus: value.policyStatus,
        } : current);
      }
      await loadPhotoRepairHistory();
      return value;
    } catch (error) {
      setPhotoBackupRestoreRehearsalError(errorMessage(error));
      return null;
    } finally {
      setPhotoBackupRestoreRehearsing(false);
    }
  }

  async function runPhotoRepairScan() {
    const libraryRoot = activeLibraryRootRef.current;
    const libraryRootProfileId = activeLibraryRootProfileIdRef.current;
    setPhotoRepairScanning(true);
    setPhotoRepairError("");
    setPhotoRepairStatus("");
    try {
      const [backupResult, recoveredResult, restoreResult, backupRestoreResult] = await Promise.all([
        photoLibraryBackupCheck({ sampleLimit: 8, libraryRoot, libraryRootProfileId }),
        props.listPhotoImportFailures({ limit: 100, libraryRoot, libraryRootProfileId }),
        photoRestoreRehearsal({ limit: 6 }),
        props.photoBackupRestoreRehearsal({
          sampleLimit: 8,
          createBackup: false,
          includeGenerated: Boolean(photoLibraryProfile?.backupPolicy?.includeGenerated),
          recordPolicy: true,
        }),
      ]);
      const backup = backupResult.value || null;
      const restore = restoreResult.value || null;
      const backupRestore = backupRestoreResult.value || null;
      const failures = recoveredResult.value?.failures || [];
      const recoveredCount = Number(recoveredResult.value?.activeTotal ?? recoveredResult.value?.total ?? failures.length) || 0;
      setPhotoBackupCheck(backup);
      setPhotoBackupCheckError("");
      setPhotoRestoreRehearsalValue(restore);
      setPhotoRestoreRehearsalError("");
      setPhotoBackupRestoreRehearsalValue(backupRestore);
      setPhotoBackupRestoreRehearsalError("");
      if (backupRestore?.policyStatus) {
        setPhotoLibraryProfile((current) => current ? {
          ...current,
          backupPolicy: backupRestore.policyStatus?.policy || current.backupPolicy,
          backupPolicyStatus: backupRestore.policyStatus,
        } : current);
      }
      setRecoveredFailures(failures);
      setRecoveredFailuresError("");
      setPhotoRepairRecoveredCount(recoveredCount);
      const issues = buildPhotoRepairIssues({
        backupCheck: backup,
        restoreRehearsal: restore,
        backupRestoreRehearsal: backupRestore,
        recoveredCount,
        visiblePhotoCount: items.length,
      });
      setPhotoRepairStatus(issues.length
        ? `${formatCount(issues.length)} repair issue${issues.length === 1 ? "" : "s"} found.`
        : uiText("No repair issues found."));
      await loadPhotoRepairHistory();
    } catch (error) {
      setPhotoRepairError(errorMessage(error));
    } finally {
      setPhotoRepairScanning(false);
    }
  }

  async function openPhotoRecoveredRepair() {
    setActiveId("recovered");
    setSearchQuery("");
    setKeywordFilter("");
    setMediaKindFilter("");
    setFavoriteOnly(false);
    setEditedOnly(false);
    setVisibilityFilter("");
    await loadRecoveredFailures();
  }

  async function handlePhotoRepairIssueAction(issue: PhotoRepairIssue) {
    if (issue.action === "relinkMissingOriginal") {
      await relinkPhotoOriginals(issue.sampleSourcePath || "");
      return;
    }
    if (issue.action === "rebuildMissingPreviews") {
      await rebuildMissingPhotoPreviews();
      return;
    }
    if (issue.action === "rebuildVisiblePreviews") {
      await rebuildVisiblePhotoPreviews();
      return;
    }
    if (issue.action === "runPreviewSweep") {
      await runPhotoPreviewSweep();
      return;
    }
    if (issue.action === "openRecovered") {
      await openPhotoRecoveredRepair();
      return;
    }
    if (issue.action === "runRestoreRehearsal") {
      await runPhotoRestoreRehearsal();
      return;
    }
    if (issue.action === "runBackupRestoreRehearsal") {
      await runPhotoBackupRestoreRehearsal(true);
      return;
    }
    if (issue.action === "cleanCatalogDrift") {
      await previewPhotoCatalogCleanup();
      return;
    }
    if (issue.action === "openRootProfiles") {
      setPhotoSettingsOpen(true);
      setPhotoRootHealthOpen((current) => {
        const next = { ...current };
        managedRootProfileRows.forEach((row) => {
          next[rootRepairKey(row.path)] = true;
        });
        return next;
      });
      return;
    }
    if (issue.action === "runBackupCheck") {
      await runPhotoLibraryBackupCheck();
    }
  }

  function photoRepairIssueActionDisabled(issue: PhotoRepairIssue): boolean {
    if (!issue.action || props.busy) return true;
    if (issue.action === "relinkMissingOriginal") return loading || photoRelinking || !issue.sampleSourcePath;
    if (issue.action === "rebuildMissingPreviews") return loading || previewRepairing;
    if (issue.action === "rebuildVisiblePreviews") return loading || previewRepairing || !items.length;
    if (issue.action === "runPreviewSweep") return loading || photoPreviewSweeping || photoBackupChecking;
    if (issue.action === "openRecovered") return recoveredFailuresLoading;
    if (issue.action === "runRestoreRehearsal") return photoRestoreRehearsing;
    if (issue.action === "runBackupRestoreRehearsal") return photoBackupRestoreRehearsing;
    if (issue.action === "cleanCatalogDrift") return photoCatalogCleaning || photoCatalogCleanupPreviewing || photoBackupChecking;
    if (issue.action === "openRootProfiles") return photoLibraryProfileSaving;
    if (issue.action === "runBackupCheck") return photoBackupChecking;
    return false;
  }

  async function applyVisibilityAction(action: "hide" | "unhide" | "delete" | "restore", sourcePaths: string[]) {
    const paths = sourcePaths.map((path) => String(path || "").trim()).filter(Boolean);
    if (!paths.length) return null;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      const result = await applyPhotoVisibilityOperation({
        action,
        sourcePaths: paths,
        ...(action === "delete" ? { deletedAt: new Date().toISOString() } : {}),
      });
      await refreshAfterVisibilityChange();
      return result.value;
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
      return null;
    } finally {
      setSavingMetadata(false);
    }
  }

  async function hidePhoto(item: PhotoItem, hidden: boolean) {
    await applyVisibilityAction(hidden ? "hide" : "unhide", [item.sourcePath]);
  }

  async function deletePhoto(item: PhotoItem) {
    await applyVisibilityAction("delete", [item.sourcePath]);
  }

  async function restorePhoto(item: PhotoItem) {
    await applyVisibilityAction("restore", [item.sourcePath]);
  }

  async function permanentlyDeletePhoto(item: PhotoItem) {
    if (!item.deletedAt) return;
    if (!await confirmPhotoAction({
      title: uiText("Delete permanently"),
      message: uiText("Permanently remove this photo from the local Photos catalog? Managed-library originals move to app trash; referenced originals stay on disk."),
      confirmLabel: uiText("Delete permanently"),
    })) return;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      await permanentlyDeletePhotos({ sourcePaths: [item.sourcePath] });
      await refreshAfterVisibilityChange();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function mergeDuplicateGroup(item: PhotoItem, keepAssetId?: string) {
    const groupId = item.duplicateGroup?.groupId || "";
    if (!groupId) return;
    if (item.duplicateGroup?.algorithm === "perceptual_dhash" && !await confirmPhotoAction({
      title: uiText("Merge near duplicates"),
      message: uiText("These photos are visually similar, not byte-identical. Move the non-kept items to Recently Deleted?"),
      confirmLabel: uiText("Merge near duplicates"),
      danger: false,
    })) return;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      await mergePhotoDuplicates({
        groupId,
        keepAssetId: keepAssetId ?? item.assetId ?? "",
      });
      await refreshAfterVisibilityChange();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function dismissDuplicateGroup(item: PhotoItem) {
    const groupId = item.duplicateGroup?.groupId || "";
    if (!groupId) return;
    if (!await confirmPhotoAction({
      title: uiText("Dismiss duplicate group"),
      message: item.duplicateGroup?.algorithm === "perceptual_dhash"
        ? uiText("Stop showing this near-duplicate group? The photos stay in your library.")
        : uiText("Stop showing this duplicate group? The photos stay in your library."),
      confirmLabel: uiText("Dismiss group"),
      danger: false,
    })) return;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      await dismissPhotoDuplicateGroup({ groupId });
      await refreshAfterVisibilityChange();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  function setLocationFromPickerPoint(point: { latitude: number; longitude: number }) {
    setLocationLatitudeDraft(formatPhotoLocationCoordinate(point.latitude));
    setLocationLongitudeDraft(formatPhotoLocationCoordinate(point.longitude));
  }

  function addDescriptionRegionDraft() {
    setDescriptionRegionsDraft((current) => {
      const next = [
        ...current,
        {
          id: `description-region-${Date.now().toString(36)}-${current.length + 1}`,
          text: "",
          x: 12,
          y: 12,
          width: 34,
          height: 18,
          confidence: "",
        },
      ];
      setDescriptionRegionSelectedIndex(next.length - 1);
      return next;
    });
  }

  function updateDescriptionRegionDraft(index: number, patch: Partial<PhotoDescriptionRegion>) {
    setDescriptionRegionsDraft((current) => current.map((region, regionIndex) => {
      if (regionIndex !== index) return region;
      return normalizePhotoDescriptionRegionDraft({
        ...region,
        ...patch,
      }) || region;
    }));
  }

  function deleteDescriptionRegionDraft(index: number) {
    setDescriptionRegionsDraft((current) => {
      const next = current.filter((_, regionIndex) => regionIndex !== index);
      setDescriptionRegionSelectedIndex(Math.max(0, Math.min(descriptionRegionSelectedIndex, next.length - 1)));
      return next;
    });
  }

  function pickLocationFromPointer(event: ReactPointerEvent<HTMLDivElement>) {
    const point = photoLocationFromClientPoint(event.clientX, event.clientY, event.currentTarget.getBoundingClientRect());
    if (!point) return;
    event.preventDefault();
    setLocationFromPickerPoint(point);
  }

  function nudgeLocationPicker(event: ReactKeyboardEvent<HTMLDivElement>) {
    const key = event.key;
    if (!["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "Home"].includes(key)) return;
    event.preventDefault();
    const current = locationPickerDraftPoint || photoLocationFromPickerPercent(50, 50);
    const step = event.shiftKey ? 5 : 1;
    if (key === "Home") {
      setLocationFromPickerPoint(photoLocationFromPickerPercent(50, 50));
      return;
    }
    const nextLatitude = current.latitude + (key === "ArrowUp" ? step : key === "ArrowDown" ? -step : 0);
    const nextLongitude = current.longitude + (key === "ArrowRight" ? step : key === "ArrowLeft" ? -step : 0);
    setLocationFromPickerPoint(photoLocationPickerPoint(nextLatitude, nextLongitude) || current);
  }

  function reverseGeocodeStatusText(scope: "lightbox" | "place") {
    if (reverseGeocodeScope !== scope) return "";
    if (reverseGeocodeError) return reverseGeocodeError;
    if (!reverseGeocodeResult) return "";
    if (reverseGeocodeResult.message) return reverseGeocodeResult.message;
    const label = String(reverseGeocodeResult.label || "").trim();
    if (!label) return "";
    if (reverseGeocodeResult.applied) return `${uiText("Applied")} ${label}`;
    return `${uiText("Found")} ${label}`;
  }

  function patchReverseGeocodeItems(rows: Array<Partial<PhotoItem> & Record<string, unknown>> | undefined) {
    (rows || []).forEach((row) => {
      const sourcePath = String(row.sourcePath || "");
      if (!sourcePath) return;
      patchItemMetadata(sourcePath, {
        locationOverride: (row.locationOverride && typeof row.locationOverride === "object" ? row.locationOverride : {}) as Record<string, unknown>,
        locationHidden: Boolean(row.locationHidden),
      });
    });
  }

  function photoItemGpsCoordinate(item: PhotoItem, key: "latitude" | "longitude") {
    const assetMetadata = item.assetMetadata && typeof item.assetMetadata === "object" ? item.assetMetadata : {};
    const exif = assetMetadata.exif && typeof assetMetadata.exif === "object" ? assetMetadata.exif as Record<string, unknown> : {};
    const exifGps = exif.gps && typeof exif.gps === "object" ? exif.gps as Record<string, unknown> : {};
    const assetGps = assetMetadata.gps && typeof assetMetadata.gps === "object" ? assetMetadata.gps as Record<string, unknown> : {};
    return parsePhotoPlaceCoordinate(exifGps[key] ?? assetGps[key]);
  }

  function lightboxLookupCoordinates(item: PhotoItem) {
    const latitude = parsePhotoPlaceCoordinate(locationLatitudeDraft) ?? photoItemGpsCoordinate(item, "latitude");
    const longitude = parsePhotoPlaceCoordinate(locationLongitudeDraft) ?? photoItemGpsCoordinate(item, "longitude");
    return latitude !== null && longitude !== null ? { latitude, longitude } : null;
  }

  async function lookupLightboxPlaceName(item: PhotoItem, apply = false) {
    const coordinates = lightboxLookupCoordinates(item);
    setReverseGeocodeScope("lightbox");
    setReverseGeocodeResult(null);
    setReverseGeocodeError("");
    if (photoSettings.noNetworkIntelligence) {
      setReverseGeocodeError(uiText("Network lookups disabled"));
      return;
    }
    if (!coordinates) {
      setReverseGeocodeError(uiText("Add latitude and longitude first."));
      return;
    }
    setReverseGeocodeLoading(true);
    try {
      const result = await reverseGeocodePhotoLocation({
        sourcePath: item.sourcePath,
        assetId: item.assetId || "",
        latitude: coordinates.latitude,
        longitude: coordinates.longitude,
        apply,
      });
      const value = result.value || { ok: false };
      setReverseGeocodeResult(value);
      if (!value.ok) {
        setReverseGeocodeError(value.message || uiText("Place lookup failed."));
        return;
      }
      if (apply) {
        patchReverseGeocodeItems(value.items);
        setLocationLabelDraft(String(value.label || ""));
        setLocationLatitudeDraft(String(value.latitude || coordinates.latitude));
        setLocationLongitudeDraft(String(value.longitude || coordinates.longitude));
        setLocationHiddenDraft(false);
        await loadPhotoOperations();
        await loadFolders();
      }
    } catch (error) {
      setReverseGeocodeError(errorMessage(error));
    } finally {
      setReverseGeocodeLoading(false);
    }
  }

  async function lookupActivePlaceName(apply = false) {
    if (!activePlace?.place) return;
    const latitude = parsePhotoPlaceCoordinate(activePlace.place.latitude);
    const longitude = parsePhotoPlaceCoordinate(activePlace.place.longitude);
    const assetIds = (activePlace.place.assetIds || []).map((assetId) => String(assetId || "")).filter(Boolean);
    setReverseGeocodeScope("place");
    setReverseGeocodeResult(null);
    setReverseGeocodeError("");
    if (photoSettings.noNetworkIntelligence) {
      setReverseGeocodeError(uiText("Network lookups disabled"));
      return;
    }
    if (latitude === null || longitude === null) {
      setReverseGeocodeError(uiText("No coordinates available."));
      return;
    }
    if (apply && !assetIds.length) {
      setReverseGeocodeError(uiText("No photos to update."));
      return;
    }
    setReverseGeocodeLoading(true);
    try {
      const result = await reverseGeocodePhotoLocation({
        latitude,
        longitude,
        assetIds,
        apply,
      });
      const value = result.value || { ok: false };
      setReverseGeocodeResult(value);
      if (!value.ok) {
        setReverseGeocodeError(value.message || uiText("Place lookup failed."));
        return;
      }
      if (apply) {
        patchReverseGeocodeItems(value.items);
        await loadPhotoOperations();
        await loadFolders();
        await loadPage(activeId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
      }
    } catch (error) {
      setReverseGeocodeError(errorMessage(error));
    } finally {
      setReverseGeocodeLoading(false);
    }
  }

  async function saveLightboxInfo(item: PhotoItem) {
    const nextOriginalCaptureDate = composePhotoDateTimeOverride(originalDateDraft, originalTimeDraft, originalTimezoneDraft);
    const nextDateOverride = composePhotoDateTimeOverride(dateDraft, timeDraft, timezoneDraft);
    const originalDateChanged = nextOriginalCaptureDate !== normalizePhotoDateTimeOverride(item.originalCaptureDate || "");
    const dateChanged = nextDateOverride !== normalizePhotoDateTimeOverride(item.dateOverride || "");
    const locationChanged = locationLabelDraft !== String(item.locationOverride?.label || "")
      || locationLatitudeDraft !== String(item.locationOverride?.latitude || "")
      || locationLongitudeDraft !== String(item.locationOverride?.longitude || "")
      || locationHiddenDraft !== Boolean(item.locationHidden);
    const locationOverride: Record<string, unknown> = {};
    if (locationLabelDraft.trim()) locationOverride.label = locationLabelDraft.trim();
    if (locationLatitudeDraft.trim()) locationOverride.latitude = locationLatitudeDraft.trim();
    if (locationLongitudeDraft.trim()) locationOverride.longitude = locationLongitudeDraft.trim();
    const localDepthControls = photoLocalDepthControlsPayload({
      mode: depthModeDraft,
      aperture: depthApertureDraft,
      focusDistance: depthFocusDistanceDraft,
      effect: depthEffectDraft,
    });
    const patch: PhotoMetadataPatch = {
      title: titleDraft,
      caption: captionDraft,
      accessibilityDescription: accessibleDescriptionDraft,
      descriptionRegions: serializePhotoDescriptionRegions(descriptionRegionsDraft),
      keywords: parseKeywordsDraft(keywordsDraft),
      dateOverride: nextDateOverride,
      locationOverride,
      locationHidden: locationHiddenDraft,
      localDepthControls,
    };
    if (originalDateChanged) patch.captureDate = nextOriginalCaptureDate;
    const saved = await savePhotoMetadata(item, patch);
    if (saved) {
      if (originalDateChanged) {
        const originalDateTime = splitPhotoDateTimeOverride(saved.originalCaptureDate || "");
        setOriginalDateDraft(originalDateTime.date);
        setOriginalTimeDraft(originalDateTime.time);
        setOriginalTimezoneDraft(originalDateTime.timezone);
      }
      await loadKeywords();
      if (dateChanged || originalDateChanged || locationChanged) {
        setDateBucketRefreshToken((token) => token + 1);
        await loadFolders();
      }
    }
  }

