  async function permanentlyDeleteSelected() {
    if (!selectedSourcePaths.length || !activeDeletedCollection) return;
    if (!await confirmPhotoAction({
      title: uiText("Delete permanently"),
      message: uiText("Permanently remove selected photos from the local Photos catalog? Managed-library originals move to app trash; referenced originals stay on disk."),
      confirmLabel: uiText("Delete permanently"),
    })) return;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      await permanentlyDeletePhotos({ sourcePaths: selectedSourcePaths });
      await refreshAfterVisibilityChange();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function cleanupRecentlyDeletedByRetention() {
    if (!activeDeletedCollection) return;
    const days = Math.max(1, Math.min(3650, Math.round(Number(recentlyDeletedRetentionDays) || 30)));
    setRecentlyDeletedRetentionDays(String(days));
    if (!await confirmPhotoAction({
      title: uiText("Delete older photos"),
      message: uiText(`Permanently remove Recently Deleted photos older than ${days} day${days === 1 ? "" : "s"} from the local Photos catalog? Managed-library originals move to app trash; referenced originals stay on disk.`),
      confirmLabel: uiText("Delete older"),
    })) return;
    setSavingMetadata(true);
    setMetadataError("");
    setRecentlyDeletedCleanupResult("");
    try {
      const result = await permanentlyDeletePhotos({ olderThanDays: days });
      const deleted = Number(result.value?.deletedAssets || 0);
      setRecentlyDeletedCleanupResult(`${uiText("Deleted")} ${formatCount(deleted)} ${deleted === 1 ? uiText("photo") : uiText("photos")}.`);
      await refreshAfterVisibilityChange();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function undoLatestPhotoOperation(operationId = "") {
    const operation = operationId
      ? photoOperations.find((candidate) => candidate.operationId === operationId)
      : latestUndoablePhotoOperation;
    const refreshDuplicatePeople = String(operation?.operationType || "").startsWith("person_label_");
    setSavingMetadata(true);
    setMetadataError("");
    setPhotoOperationError("");
    try {
      await undoPhotoOperation({ operationId });
      await refreshAfterVisibilityChange();
      if (refreshDuplicatePeople) await loadDuplicatePeople();
    } catch (error) {
      setPhotoOperationError(errorMessage(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function updateSelectedKeywords(action: "add" | "remove") {
    const draftKeywords = parseKeywordsDraft(bulkKeywordsDraft);
    if (!selectedSourcePaths.length || !draftKeywords.length) return;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      const updates: Array<Record<string, unknown>> = [];
      for (const item of selectedItems) {
        const current = parseKeywordsDraft(item.keywords || []);
        const removeKeys = new Set(draftKeywords.map((keyword) => keyword.toLocaleLowerCase()));
        const nextKeywords = action === "remove"
          ? current.filter((keyword) => !removeKeys.has(keyword.toLocaleLowerCase()))
          : parseKeywordsDraft([...current, ...draftKeywords]);
        updates.push({
          sourcePath: item.sourcePath,
          assetId: item.assetId || "",
          keywords: nextKeywords,
        });
      }
      if (updates.length) {
        await updatePhotoAssetsMetadata({
          label: action === "remove" ? uiText("Removed selected keywords") : uiText("Added selected keywords"),
          items: updates,
        });
      }
      setBulkKeywordsDraft("");
      setSelectedSources(new Set());
      await loadFolders();
      await loadKeywords();
      await loadPhotoOperations();
      await loadPage(activeId, 0, sort, searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function offsetSelectedDates() {
    const days = parsePhotoDateOffsetDays(bulkDateOffsetDays);
    if (!selectedItems.length || !days) return;
    const nextBySource = new Map<string, Partial<PhotoItem>>();
    const updates: Array<Record<string, unknown>> = [];
    setSavingMetadata(true);
    setMetadataError("");
    try {
      for (const item of selectedItems) {
        const sourceDate = item.dateOverride || item.captureDate || item.originalCaptureDate || item.addedAt || item.scanDate || item.createdAt || "";
        const nextDate = shiftPhotoDateByDays(sourceDate, days);
        if (!nextDate) continue;
        nextBySource.set(item.sourcePath, {
          dateOverride: nextDate,
          captureDate: restoredPhotoCaptureDate(item, nextDate),
        });
        updates.push({
          sourcePath: item.sourcePath,
          assetId: item.assetId || "",
          dateOverride: nextDate,
        });
      }
      if (!nextBySource.size) {
        setMetadataError(uiText("No selected photos have dates to adjust."));
        return;
      }
      await updatePhotoAssetsMetadata({
        label: uiText("Offset selected dates"),
        items: updates,
      });
      setItems((current) => current.map((item) => {
        const patch = nextBySource.get(item.sourcePath);
        return patch ? { ...item, ...patch } : item;
      }));
      setBulkDateOffsetDays("0");
      setDateBucketRefreshToken((token) => token + 1);
      await loadFolders();
      await loadPhotoOperations();
      await loadPage(
        activeId,
        0,
        sort,
        searchQuery,
        keywordFilter,
        mediaKindFilter,
        favoriteOnly,
        editedOnly,
        notInAlbumOnly,
        personFilter,
        statusFilter,
        minQualityFilter,
        dateFromFilter,
        dateToFilter,
        sourceFilter,
        fileTypeFilter,
        duplicateOnly,
        locationFilter,
        cameraFilter,
        albumFilter,
        visibilityFilter
      );
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

