  async function applyKeywordShortcut(keyword: PhotoKeyword) {
    const keywordName = String(keyword.name || "").trim();
    if (!keywordName || props.busy || savingMetadata) return;
    const targetItems = lightItem ? [lightItem] : selectedItems;
    if (!targetItems.length) return;
    const keywordKey = keywordName.toLocaleLowerCase();
    const removeKeyword = targetItems.every((item) => (
      parseKeywordsDraft(item.keywords || []).some((itemKeyword) => itemKeyword.toLocaleLowerCase() === keywordKey)
    ));
    const nextBySource = new Map<string, string[]>();
    setSavingMetadata(true);
    setMetadataError("");
    try {
      for (const item of targetItems) {
        const current = parseKeywordsDraft(item.keywords || []);
        const nextKeywords = removeKeyword
          ? current.filter((itemKeyword) => itemKeyword.toLocaleLowerCase() !== keywordKey)
          : parseKeywordsDraft([...current, keywordName]);
        nextBySource.set(item.sourcePath, nextKeywords);
        await updatePhotoAssetMetadata({
          sourcePath: item.sourcePath,
          assetId: item.assetId || "",
          keywords: nextKeywords,
        });
      }
      setItems((current) => current.map((item) => {
        const keywords = nextBySource.get(item.sourcePath);
        return keywords ? { ...item, keywords } : item;
      }));
      if (lightItem && nextBySource.has(lightItem.sourcePath)) {
        setKeywordsDraft((nextBySource.get(lightItem.sourcePath) || []).join(", "));
      }
      await loadFolders();
      await loadKeywords();
      await loadPage(
        activeId,
        0,
        sort,
        searchQuery,
        keywordFilter,
        mediaKindFilter,
        favoriteOnly,
        editedOnly,
        notInAlbumOnly,
        personFilter,
        statusFilter,
        minQualityFilter,
        dateFromFilter,
        dateToFilter,
        sourceFilter,
        fileTypeFilter,
        duplicateOnly,
        locationFilter,
        cameraFilter,
        albumFilter,
        visibilityFilter
      );
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

  async function mergeSelectedDuplicateGroups() {
    if (!selectedDuplicateGroupIds.length) return;
    const selectedDuplicateGroups = selectedItems
      .map((item) => item.duplicateGroup)
      .filter((group): group is PhotoDuplicateGroup => Boolean(group));
    if (selectedDuplicateGroups.some((group) => group.algorithm === "perceptual_dhash") && !await confirmPhotoAction({
      title: uiText("Merge near duplicates"),
      message: uiText("Some selected groups are visually similar, not byte-identical. Move each non-kept item to Recently Deleted?"),
      confirmLabel: uiText("Merge groups"),
      danger: false,
    })) return;
    setSavingMetadata(true);
    setMetadataError("");
    try {
      for (const groupId of selectedDuplicateGroupIds) {
        await mergePhotoDuplicates({ groupId });
      }
      await refreshAfterVisibilityChange();
    } catch (error) {
      setMetadataError(error instanceof Error ? error.message : String(error));
    } finally {
      setSavingMetadata(false);
    }
  }

