  async function runSemanticPhotoSearch(query: string) {
    const trimmed = query.trim();
    if (trimmed.length < 2) {
      setSemanticError(uiText("Type at least 2 characters to search by meaning."));
      return;
    }
    setSemanticBusy(true);
    setSemanticError("");
    try {
      const result = await semanticSearchPhotos({ query: trimmed, limit: 60 });
      setSemanticResults(result);
      if (result && !result.available) {
        setSemanticError(result.reason || uiText("On-device semantic search model is not installed."));
      } else if (result && result.results.length === 0) {
        setSemanticError(uiText("No semantic matches in this library yet."));
      }
    } catch (error) {
      setSemanticResults(null);
      setSemanticError(errorMessage(error));
    } finally {
      setSemanticBusy(false);
    }
  }

