  async function updateManagedPhotoRootPolicy(profile: PhotoManagedRootProfile, patch: Partial<PhotoManagedRootPolicy>) {
    const profilePath = String(profile.path || "").trim();
    if (!profilePath) return;
    const current = photoManagedRootPolicyDefaults(profile);
    const next: PhotoManagedRootPolicy = { ...current, ...patch };
    if (Object.prototype.hasOwnProperty.call(patch, "externalBackupCovered")) {
      next.externalBackupCheckedAt = patch.externalBackupCovered ? new Date().toISOString() : "";
      if (patch.externalBackupCovered && !String(next.externalBackupLabel || "").trim()) {
        next.externalBackupLabel = uiText("External backup");
      }
    }
    setPhotoLibraryProfileSaving(true);
    setPhotoLibraryProfileError("");
    try {
      const result = await savePhotoLibrarySettings({
        defaultStorageMode: importStorageMode,
        managedRootPolicy: {
          profileId: profile.profileId,
          path: profilePath,
          name: String(profile.name || "").trim() || fileName(profilePath) || uiText("Managed library"),
          builtIn: Boolean(profile.builtIn),
          policy: next,
        },
      });
      setPhotoLibraryProfile(result.value || null);
      const updatedProfile = findPhotoManagedRootProfile(result.value || null, profilePath);
      const updatesImportDestination = cleanImportManagedRoot
        ? profilePath === cleanImportManagedRoot
        : Boolean(updatedProfile?.isDefault);
      if (importStorageMode === "managed" && updatesImportDestination) {
        applyImportKeepFolderDefault(result.value || null, profilePath);
      }
    } catch (error) {
      setPhotoLibraryProfileError(errorMessage(error));
    } finally {
      setPhotoLibraryProfileSaving(false);
    }
  }

  async function renameManagedPhotoRootProfile(profile: PhotoManagedRootProfile, draftName: string) {
    if (profile.builtIn) return;
    const profilePath = String(profile.path || "").trim();
    if (!profilePath) return;
    const currentName = String(profile.name || "").trim() || fileName(profilePath) || uiText("Managed library");
    const nextName = String(draftName || "").replace(/\s+/g, " ").trim().slice(0, 160);
    if (!nextName || nextName === currentName) return;
    setPhotoLibraryProfileSaving(true);
    setPhotoLibraryProfileError("");
    try {
      const result = await savePhotoLibrarySettings({
        defaultStorageMode: importStorageMode,
        managedRootPolicy: {
          profileId: profile.profileId,
          path: profilePath,
          name: nextName,
          builtIn: Boolean(profile.builtIn),
          policy: photoManagedRootPolicyDefaults(profile),
        },
      });
      setPhotoLibraryProfile(result.value || null);
      setManagedRootRenameDrafts((current) => ({
        ...current,
        [profile.profileId || profilePath]: nextName,
      }));
    } catch (error) {
      setPhotoLibraryProfileError(errorMessage(error));
    } finally {
      setPhotoLibraryProfileSaving(false);
    }
  }

