  async function removeSourcesFromActiveMemory(sourcePaths: string[]) {
    if (!activeMemoryId) return;
    const cleanPaths = [...new Set(sourcePaths.map((path) => String(path || "").trim()).filter(Boolean))];
    if (!cleanPaths.length) return;
    const nextPreferences = addPhotoMemoryRemovedItems(photoCurationPreferencesValue, activeMemoryId, cleanPaths);
    const memorySources = activeMemory?.memory?.sourcePaths || [];
    const nextRemoved = new Set(photoMemoryRemovedItems(nextPreferences, activeMemoryId));
    const remaining = memorySources.length
      ? memorySources.filter((path) => !nextRemoved.has(path)).length
      : Math.max(0, (activeMemory?.count || items.length) - cleanPaths.length);
    await persistPhotoCurationPreferences(nextPreferences);
    setSelectedSources(new Set());
    if (lightItem && cleanPaths.includes(lightItem.sourcePath)) setLightbox(null);
    if (remaining < 2) {
      setActiveId("memories");
    } else {
      refreshCurrentPhotoPage();
    }
  }

  async function exportActiveMemoryMovie(folder: PhotoFolder | null = activeMemory) {
    const memoryId = folder?.memoryId || folder?.memory?.memoryId || "";
    if (!memoryId) return;
    setMemoryMovieExporting(true);
    setUserMemoryError("");
    try {
      const memorySettings = folder?.memory?.movieSettings && typeof folder.memory.movieSettings === "object" ? folder.memory.movieSettings : null;
      const memorySetting = <T,>(key: keyof NonNullable<PhotoMemory["movieSettings"]>, fallback: T): T => {
        const value = memorySettings?.[key];
        return value === undefined || value === null ? fallback : value as T;
      };
      const currentMemoryMusic = photoSlideshowProjectMusic === "custom" && photoSlideshowProjectMusicPath ? "custom" : "calm";
      const savedMusicPath = String(memorySetting("musicPath", memorySetting("audioPath", photoSlideshowProjectMusicPath)) || "");
      const rawMemoryMusic = String(memorySetting("music", currentMemoryMusic) || currentMemoryMusic);
      const memoryMusic = rawMemoryMusic === "custom" ? (savedMusicPath ? "custom" : "calm") : rawMemoryMusic;
      const memoryTitle = folder?.memory?.name || folder?.name || uiText("Memory");
      const memorySourceLabel = folder?.memory?.subtitle || folder?.memory?.dateRangeLabel || uiText("Memory");
      await exportPhotoMemoryMovie({
        memoryId,
        title: memoryTitle,
        sourceLabel: memorySourceLabel,
        theme: memorySetting("theme", "ken-burns"),
        themeTimelinePreset: memorySetting("themeTimelinePreset", photoSlideshowProjectThemeTimelinePreset),
        themeTemplateName: memorySetting("themeTemplateName", photoSlideshowProjectThemeTemplateName),
        themeTemplatePalette: memorySetting("themeTemplatePalette", photoSlideshowProjectThemeTemplatePalette),
        themeTemplateTypography: memorySetting("themeTemplateTypography", photoSlideshowProjectThemeTemplateTypography),
        themeTemplateBackdrop: memorySetting("themeTemplateBackdrop", photoSlideshowProjectThemeTemplateBackdrop),
        themeTemplateLayout: memorySetting("themeTemplateLayout", photoSlideshowProjectThemeTemplateLayout),
        themeTemplateBackdropIntensity: memorySetting("themeTemplateBackdropIntensity", photoSlideshowProjectThemeTemplateBackdropIntensity),
        themeTemplateStageWidth: memorySetting("themeTemplateStageWidth", photoSlideshowProjectThemeTemplateStageWidth),
        themeTemplateFrameStyle: memorySetting("themeTemplateFrameStyle", photoSlideshowProjectThemeTemplateFrameStyle),
        themeTemplateChromeDensity: memorySetting("themeTemplateChromeDensity", photoSlideshowProjectThemeTemplateChromeDensity),
        themeTemplateCaptionPreset: memorySetting("themeTemplateCaptionPreset", photoSlideshowProjectThemeTemplateCaptionPreset),
        themeTemplateRegionMap: memorySetting("themeTemplateRegionMap", currentPhotoSlideshowTemplateRegionMap()),
        music: memoryMusic,
        audioPath: memoryMusic === "custom" ? savedMusicPath : "",
        audioVolume: memorySetting("audioVolume", Math.max(0, Math.min(100, photoSlideshowProjectAudioVolume)) / 100),
        audioFadeMs: memorySetting("audioFadeMs", Math.max(0, Math.min(10000, photoSlideshowProjectAudioFadeMs))),
        audioStartMs: memorySetting("audioStartMs", Math.max(0, Math.min(3_600_000, photoSlideshowProjectAudioStartMs))),
        audioEndMs: memorySetting("audioEndMs", Math.max(0, Math.min(3_600_000, photoSlideshowProjectAudioEndMs))),
        audioPlacementStartSourcePath: memorySetting("audioPlacementStartSourcePath", photoSlideshowProjectAudioPlacementStartSourcePath),
        audioPlacementEndSourcePath: memorySetting("audioPlacementEndSourcePath", photoSlideshowProjectAudioPlacementEndSourcePath),
        includeTitleCard: memorySetting("includeTitleCard", true),
        titleCardTitle: String(memorySetting("titleCardTitle", photoSlideshowProjectTitleCardTitle.trim()) || photoSlideshowProjectTitleCardTitle.trim() || memoryTitle),
        titleCardSubtitle: String(memorySetting("titleCardSubtitle", photoSlideshowProjectTitleCardSubtitle.trim()) || photoSlideshowProjectTitleCardSubtitle.trim() || memorySourceLabel),
        titleCardDurationMs: memorySetting("titleCardDurationMs", Math.max(1500, Math.min(15000, photoSlideshowProjectTitleCardDurationMs))),
        titleCardPalette: memorySetting("titleCardPalette", photoSlideshowProjectTitleCardPalette),
        titleCardLayout: memorySetting("titleCardLayout", photoSlideshowProjectTitleCardLayout),
        titleCardFontScale: memorySetting("titleCardFontScale", photoSlideshowProjectTitleCardFontScale),
        titleCardShowFooter: memorySetting("titleCardShowFooter", photoSlideshowProjectTitleCardShowFooter),
        timelineItems: cleanPhotoSlideshowTimelineItems(photoSlideshowProjectTimelineItems, folder?.memory?.sourcePaths || [], slideshowIntervalMs),
        transitionEffect: memorySetting("transitionEffect", photoSlideshowProjectTransitionEffect),
        transitionDurationMs: memorySetting("transitionDurationMs", photoSlideshowProjectTransitionEffect === "cut" ? 0 : Math.max(0, Math.min(3000, photoSlideshowProjectTransitionDurationMs))),
        intervalMs: memorySetting("intervalMs", slideshowIntervalMs),
        fitMode: memorySetting("fitMode", slideshowFitMode),
        videoRenderFormat: exportVideoRenderFormat,
        videoRenderQuality: exportVideoRenderQuality,
        renderMaxDimension: effectiveExportRenderMaxDimensionNumber,
      });
      await loadFolders();
    } catch (error) {
      setUserMemoryError(errorMessage(error));
    } finally {
      setMemoryMovieExporting(false);
    }
  }

  async function createUserMemoryFromCurrentView() {
    setUserMemorySaving(true);
    setUserMemoryError("");
    try {
      const queueSourceItems = selectedSources.size ? items : await loadCurrentSlideshowItems();
      const sourcePaths = photoSlideshowProjectSourcePaths(queueSourceItems, selectedSources.size ? selectedSources : undefined);
      if (sourcePaths.length < 2) {
        setUserMemoryError(uiText("Choose at least two visible photos for a memory."));
        return;
      }
      const name = userMemoryNameDraft.trim() || userMemorySource.defaultName || active?.name || uiText("Memory");
      const sourceLabel = userMemorySource.sourceLabel || (selectedSources.size ? uiText("Selection") : active?.name || uiText("Current view"));
      const result = await savePhotoUserMemory({
        name,
        subtitle: sourceLabel,
        sourcePaths,
        coverSourcePath: sourcePaths[0] || "",
      });
      const savedMemoryId = result.value?.memoryId || "";
      await photoUserMemories({});
      await loadFolders();
      setUserMemoryNameDraft("");
      setSelectedSources(new Set());
      if (savedMemoryId) {
        setActiveId(`memory:${savedMemoryId}`);
        refreshCurrentPhotoPage(`memory:${savedMemoryId}`);
      }
    } catch (error) {
      setUserMemoryError(errorMessage(error));
    } finally {
      setUserMemorySaving(false);
    }
  }

