  async function shareSelectedOriginals() {
    if (!selectedSourcePaths.length) return;
    let sourcePathsForEvent = selectedSourcePaths;
    let pathsForShare = selectedSourcePaths;
    let shareAction = "native_share";
    let fallbackAction = "share_fallback_reveal";
    let strippedLocation = false;
    let skippedCount = 0;
    const shareShouldStripLocation = Boolean(
      photoSettingsRef.current.stripLocationOnExport
      || exportStripLocation
      || readStoredPhotoLocalSettings(PHOTO_LOCAL_SETTINGS_KEY).stripLocationOnExport
    );
    if (shareShouldStripLocation) {
      const exportResult = await exportPhotoSelection(selectedSourcePaths, "export", undefined, {
        stripLocation: true,
        exportVariant: "rendered",
        renderFormat: "jpeg",
        renderQuality: 92,
        renderMaxDimension: 0,
        preserveColorProfile: true,
        targetColorProfile: "source",
        layout: "flat",
        filenameMode: "original",
        allowRenderFallback: false,
        revealAfterExport: false,
      });
      if (!exportResult) return;
      setLastPhotoSelectionExport(exportResult);
      const shareableRows = (exportResult.items || []).filter(photoSelectionExportRowIsStripLocationShareable);
      pathsForShare = [...new Set(shareableRows.map((row) => String(row.targetPath || "").trim()).filter(Boolean))];
      sourcePathsForEvent = [...new Set(shareableRows.map((row) => String(row.sourcePath || "").trim()).filter(Boolean))];
      skippedCount = Math.max(0, selectedSourcePaths.length - sourcePathsForEvent.length);
      strippedLocation = true;
      shareAction = "native_share_strip_location";
      fallbackAction = "share_fallback_reveal_strip_location";
      if (skippedCount > 0) {
        setMetadataError(`${uiText("Strip-location share skipped")} ${formatCount(skippedCount)} ${skippedCount === 1 ? uiText("item") : uiText("items")}.`);
      } else {
        setMetadataError("");
      }
      if (!pathsForShare.length) return;
    }
    const result = await sharePaths(pathsForShare);
    if (!result?.shared && result?.fallback !== "reveal") return;
    void recordPhotoAssetEvent({
      eventType: "shared",
      sourcePaths: sourcePathsForEvent,
      metadata: {
        surface: "photos-bulk-bar",
        action: result.shared ? shareAction : fallbackAction,
        strippedLocation,
        targetCount: pathsForShare.length,
        skippedCount,
      },
    }).then(() => {
      void loadFolders();
    }).catch(() => {
      // Sharing should not be interrupted if the local event log is unavailable.
    });
  }

  function relatedMediaFilePath(pair: PhotoMediaPair | null | undefined) {
    return String(pair?.relatedSourcePath || "").trim();
  }

  function relatedMediaFileAvailable(pair: PhotoMediaPair | null | undefined) {
    return Boolean(relatedMediaFilePath(pair)) && photoMediaPairStatusKind(pair) === "available";
  }

  function revealRelatedMedia(pair: PhotoMediaPair) {
    const relatedPath = relatedMediaFilePath(pair);
    if (!relatedPath || !relatedMediaFileAvailable(pair)) return;
    void revealPath(relatedPath);
  }

  function openRelatedMedia(pair: PhotoMediaPair) {
    const relatedPath = relatedMediaFilePath(pair);
    if (!relatedPath || !relatedMediaFileAvailable(pair)) return;
    void openPath(relatedPath);
  }

  async function shareRelatedMedia(item: PhotoItem | null, pair: PhotoMediaPair) {
    const relatedPath = relatedMediaFilePath(pair);
    if (!item?.sourcePath || !relatedPath || !relatedMediaFileAvailable(pair)) return;
    const result = await sharePaths([relatedPath]);
    if (!result?.shared && result?.fallback !== "reveal") return;
    void recordPhotoAssetEvent({
      eventType: "shared",
      sourcePaths: [item.sourcePath],
      metadata: {
        surface: "photos-related-media",
        action: result.shared ? "native_share_related_media" : "share_fallback_reveal_related_media",
        pairKind: pair.pairKind || "",
        relatedSourcePath: relatedPath,
      },
    }).then(() => {
      void loadFolders();
    }).catch(() => {
      // Companion file sharing should not fail because the local event log is unavailable.
    });
  }

