  async function reassignSelectedMatches() {
    const target = bulkMatchTarget.replace(/\s+/g, " ").trim();
    const ids = selectedMatchCandidateIds;
    if (!ids.length || !target) return;
    if (!await confirmPhotoAction({
      title: uiText("Move selected matches"),
      message: `${uiText("Move")} ${formatCount(ids.length)} ${ids.length === 1 ? uiText("selected match") : uiText("selected matches")} ${uiText("to")} ${target}?`,
      confirmLabel: uiText("Move matches"),
      danger: false,
    })) return;
    setBulkMatchSaving(true);
    setPersonMatchError("");
    try {
      for (const candidateId of ids) {
        await reassignCandidatePerson(candidateId, target);
      }
      setBulkMatchTarget("");
      setSelectedSources(new Set());
      refreshCurrentPhotoPage();
      await loadPhotoOperations();
    } catch (error) {
      setPersonMatchError(error instanceof Error ? error.message : String(error));
    } finally {
      setBulkMatchSaving(false);
    }
  }

