  async function saveCurrentSortAsManualAlbumOrder() {
    if (!activeAlbum?.albumId) return;
    setAlbumItemError("");
    setAlbumOrderNotice("");
    if (!manualAlbumOrderScopeIsWhole) {
      setAlbumItemError(uiText("Clear search and filters before changing custom order."));
      return;
    }
    if (sort === "manual") {
      setAlbumItemError(uiText("Choose a different sort before saving a custom order."));
      return;
    }
    setAlbumItemSaving(true);
    try {
      const nextOrder = await loadManualAlbumSourceOrder(sort);
      if (nextOrder.length < 2) return;
      const result = await reorderPhotoAlbumItems({ albumId: activeAlbum.albumId, sourcePaths: nextOrder });
      recordManualAlbumReorderResult(result);
      await loadFolders();
      await loadPhotoOperations();
      setSort("manual");
      loadPage(activeId, 0, "manual", searchQuery, keywordFilter, mediaKindFilter, favoriteOnly, editedOnly);
    } catch (error) {
      setAlbumItemError(error instanceof Error ? error.message : String(error));
    } finally {
      setAlbumItemSaving(false);
    }
  }

