          {recoveredFailuresError && !activeRecoveredCollection && <small className="warn">{recoveredFailuresError}</small>}
          {photoRestoreRehearsalError && <small className="warn">{photoRestoreRehearsalError}</small>}
          {photoBackupRestoreRehearsalError && <small className="warn">{photoBackupRestoreRehearsalError}</small>}
          {photoRepairHistoryError && <small className="warn">{photoRepairHistoryError}</small>}
          {photoRepairError && <small className="warn">{photoRepairError}</small>}
