function photoMediaFilterValue(value: string): PhotoMediaFilter {
  return value === "image"
    || value === "video"
    || value === "screenshot"
    || value === "screen_recording"
    || value === "panorama"
    || value === "portrait"
    || value === "burst"
    || value === "time_lapse"
    || value === "raw"
    || value === "live_photo"
    || value === "other"
    ? value
    : "";
}

function photoStatusFilterValue(value: string): PhotoStatusFilter {
  return value === "pending" || value === "accepted" || value === "uncertain" || value === "rejected" ? value : "";
}

function photoVisibilityFilterValue(value: string): PhotoVisibilityFilter {
  return value === "all" || value === "hidden" || value === "deleted" ? value : "";
}

function PersonChips(props: { people: NonNullable<PhotoItem["people"]>; count: number }) {
  if (!props.people.length && !props.count) return null;
  const shown = props.people.slice(0, 3);
  const overflow = Math.max(0, props.count - shown.length);
  return (
    <span className="photo-person-chips">
      {shown.map((person) => <span key={person.candidateId}>{person.personName}</span>)}
      {overflow > 0 && <span>+{overflow}</span>}
    </span>
  );
}
